INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('79a35ed0-9fb5-5fae-a85d-3680a6ae7603', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 6, 6, 'There the centurion found a ship of Alexandria sailing for Italy, and he put us on board.'),
  ('c4638ccf-f2ca-5621-af84-6bcbd8d9b19c', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 7, 7, 'When we had sailed slowly many days, and had come with difficulty opposite Cnidus, the wind not allowing us further, we sailed under the lee of Crete, opposite Salmone.'),
  ('d6bfacf4-2ca5-55f9-af9b-7f22f7fb0c80', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 8, 8, 'With difficulty sailing along it we came to a certain place called Fair Havens, near the city of Lasea.'),
  ('5c5bc91a-5976-5906-af2e-83d8e9c0ee33', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 9, 9, 'When much time had passed and the voyage was now dangerous, because the Fast had now already gone by, Paul admonished them,'),
  ('6e4ea8aa-8305-53bf-aee7-036cd155ab14', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 10, 10, 'and said to them, "Sirs, I perceive that the voyage will be with injury and much loss, not only of the cargo and the ship, but also of our lives."'),
  ('b4e386da-7918-5154-a806-b9f1df0f3b67', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 11, 11, 'But the centurion gave more heed to the master and to the owner of the ship than to those things which were spoken by Paul.'),
  ('65edfcfa-a536-541f-a32d-c3680c419b70', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 12, 12, 'Because the haven was not suitable to winter in, the majority advised going to sea from there, if by any means they could reach Phoenix, and winter there, which is a port of Crete, looking northeast and southeast.'),
  ('3479467a-c292-545d-a601-33adecc12233', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 13, 13, 'When the south wind blew softly, supposing that they had obtained their purpose, they weighed anchor and sailed along Crete, close to shore.'),
  ('dc14f3ef-7bb0-50d0-a337-a06b7588e55e', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 14, 14, 'But before long, a stormy wind beat down from shore, which is called Euroclydon.'),
  ('215d3361-ca7b-5c90-a8e0-fdabecef8811', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 15, 15, 'When the ship was caught, and couldn''t face the wind, we gave way to it, and were driven along.'),
  ('6ae374c6-82ba-5f8d-abba-9096f5ece125', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 16, 16, 'Running under the lee of a small island called Clauda, we were able, with difficulty, to secure the boat.'),
  ('b637da49-9d12-5415-ac7d-000e181ccf44', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 17, 17, 'After they had hoisted it up, they used cables to help reinforce the ship. Fearing that they would run aground on the Syrtis sand bars, they lowered the sea anchor, and so were driven along.'),
  ('e5ebf1ff-0c95-5c6d-a9af-0c5138e039a4', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 18, 18, 'As we labored exceedingly with the storm, the next day they began to throw things overboard.'),
  ('3a5b4eed-27b4-556c-a275-4c517ffcd788', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 19, 19, 'On the third day, they threw out the ship''s tackle with their own hands.'),
  ('390a0736-96ed-5054-a6c0-6d67a93f7989', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 20, 20, 'When neither sun nor stars shone on us for many days, and no small storm pressed on us, all hope that we would be saved was now taken away.'),
  ('99651069-d1b9-5025-a09f-98e821fd871e', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 21, 21, 'When they had been long without food, Paul stood up in the middle of them, and said, "Sirs, you should have listened to me, and not have set sail from Crete, and have gotten this injury and loss.'),
  ('69529ff8-58e0-5867-a9b2-dfbc42967049', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 22, 22, 'Now I exhort you to cheer up, for there will be no loss of life among you, but only of the ship.'),
  ('98e131a9-6e64-5321-ae8f-a69b44bd0fda', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 23, 23, 'For there stood by me this night an angel, belonging to the God whose I am and whom I serve,'),
  ('861db3d4-9374-5303-a1cf-98da694dcb68', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 24, 24, 'saying, ''Don''t be afraid, Paul. You must stand before Caesar. Behold, God has granted you all those who sail with you.'''),
  ('1a59c925-6bc5-5076-a1a4-845474d425c8', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 25, 25, 'Therefore, sirs, cheer up! For I believe God, that it will be just as it has been spoken to me.'),
  ('5a3e45d4-b2cf-56e0-a1a7-7ee4976b0fdb', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 26, 26, 'But we must run aground on a certain island."'),
  ('68e37eed-bc09-52cb-aadc-197089ba19fe', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 27, 27, 'But when the fourteenth night had come, as we were driven back and forth in the Adriatic Sea, about midnight the sailors surmised that they were drawing near to some land.'),
  ('1c1a5f88-ab9c-555c-ad99-1c5af0cc9a25', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 28, 28, 'They took soundings, and found twenty fathoms. After a little while, they took soundings again, and found fifteen fathoms.'),
  ('215ba999-73cc-5d15-a339-2f29e90bd9ad', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 29, 29, 'Fearing that we would run aground on rocky ground, they let go four anchors from the stern, and wished for daylight.'),
  ('c721bd45-ca48-5f8c-aaec-096be5b2d526', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 30, 30, 'As the sailors were trying to flee out of the ship, and had lowered the boat into the sea, pretending that they would lay out anchors from the bow,'),
  ('244f4077-cdf8-5152-a600-870195f2e366', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 31, 31, 'Paul said to the centurion and to the soldiers, "Unless these stay in the ship, you can''t be saved."'),
  ('aef20f55-dc6d-5130-ad8b-5ae571200363', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 32, 32, 'Then the soldiers cut away the ropes of the boat, and let it fall off.'),
  ('7af44b1f-7cfc-5361-a01b-6724e82e4abb', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 33, 33, 'While the day was coming on, Paul begged them all to take some food, saying, "This day is the fourteenth day that you wait and continue fasting, having taken nothing.'),
  ('65c47e93-c3d8-5c09-a763-21469d4031f6', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 34, 34, 'Therefore I beg you to take some food, for this is for your safety; for not a hair will perish from any of your heads."'),
  ('214cb295-8f56-509a-ad9e-ea48bf8856dc', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 35, 35, 'When he had said this, and had taken bread, he gave thanks to God in the presence of all, and he broke it, and began to eat.'),
  ('b319189e-dbab-54e5-aca7-4f6e9604ddf1', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 36, 36, 'Then they all cheered up, and they also took food.'),
  ('22b5864b-30bc-5b7b-a585-885c90fded35', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 37, 37, 'In all, we were two hundred seventy-six souls on the ship.'),
  ('b41f5be2-6538-5d32-a579-f7993a9b6cad', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 38, 38, 'When they had eaten enough, they lightened the ship, throwing out the wheat into the sea.'),
  ('4365fe49-4d71-5692-a1fb-5930247a6199', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 39, 39, 'When it was day, they didn''t recognize the land, but they noticed a certain bay with a beach, and they decided to try to drive the ship onto it.'),
  ('8ed06376-e81e-5c76-a3fb-9ba71d6e1a0e', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 40, 40, 'Casting off the anchors, they left them in the sea, at the same time untying the rudder ropes. Hoisting up the foresail to the wind, they made for the beach.'),
  ('1fc57bde-408f-5518-ac62-5d47e99d32a0', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 41, 41, 'But coming to a place where two seas met, they ran the vessel aground. The bow struck and remained immovable, but the stern began to break up by the violence of the waves.'),
  ('eac7dc72-5e4c-5931-a78e-f9026dfa4eb8', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 42, 42, 'The soldiers'' counsel was to kill the prisoners, so that none of them would swim out and escape.'),
  ('d9b913c6-425a-50ed-a5df-885811152368', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 43, 43, 'But the centurion, desiring to save Paul, stopped them from their purpose, and commanded that those who could swim should throw themselves overboard first to go toward the land;'),
  ('a113b304-3394-50eb-a58b-0b799c0aa2bf', 'b6c13b6c-c277-54f8-a6c0-3f430cfe2b43', NULL, 44, 44, 'and the rest should follow, some on planks, and some on other things from the ship. So it happened that they all escaped safely to the land.'),
  ('ff7e27c3-caa6-5121-a586-1b03860094a8', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 1, 1, 'When we had escaped, then they learned that the island was called Malta.'),
  ('c9927c68-92fa-5441-af98-05f0c5bef421', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 2, 2, 'The natives showed us uncommon kindness; for they kindled a fire, and received us all, because of the present rain, and because of the cold.'),
  ('df2a1cda-f012-5c64-a3fe-616758859fe4', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 3, 3, 'But when Paul had gathered a bundle of sticks and laid them on the fire, a viper came out because of the heat, and fastened on his hand.'),
  ('2b9b0a07-5543-5bba-af7b-af70ad3142e1', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 4, 4, 'When the natives saw the creature hanging from his hand, they said one to another, "No doubt this man is a murderer, whom, though he has escaped from the sea, yet Justice has not allowed to live."'),
  ('209f0529-8b18-584b-a92f-eba512e85bcf', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 5, 5, 'However he shook off the creature into the fire, and wasn''t harmed.'),
  ('d5232983-f2d1-5423-a693-01ed57acbd12', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 6, 6, 'But they expected that he would have swollen or fallen down dead suddenly, but when they watched for a long time and saw nothing bad happen to him, they changed their minds, and said that he was a god.'),
  ('67c69a2c-9bff-5545-a545-84c801a2f603', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 7, 7, 'Now in the neighborhood of that place were lands belonging to the chief man of the island, named Publius, who received us, and courteously entertained us for three days.'),
  ('8bb99e28-563d-52b6-ade9-4c499d912761', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 8, 8, 'It happened that the father of Publius lay sick of fever and dysentery. Paul entered in to him, prayed, and laying his hands on him, healed him.'),
  ('c9fb819e-a938-5d55-aa66-d039b43eb942', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 9, 9, 'Then when this was done, the rest also who had diseases in the island came, and were cured.'),
  ('861e0ba1-e47b-5968-a391-dcf484ad8733', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 10, 10, 'They also honored us with many honors, and when we sailed, they put on board the things that we needed.'),
  ('b301f36a-90af-5def-aaa2-dcaa89e53297', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 11, 11, 'After three months, we set sail in a ship of Alexandria which had wintered in the island, whose sign was "The Twin Brothers."'),
  ('01130a18-7b8c-51be-a854-7f48a1d032c9', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 12, 12, 'Touching at Syracuse, we stayed there three days.'),
  ('6f7522e2-6cf1-54aa-a9a6-9528824293c3', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 13, 13, 'From there we circled around and arrived at Rhegium. After one day, a south wind sprang up, and on the second day we came to Puteoli,'),
  ('fca78afb-1467-5906-a986-40218a289cde', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 14, 14, 'where we found brothers, and were entreated to stay with them for seven days. So we came to Rome.'),
  ('f432c67f-56a7-524e-a4e9-f230919f0f8e', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 15, 15, 'From there the brothers, when they heard of us, came to meet us as far as The Market of Appius and The Three Taverns. When Paul saw them, he thanked God, and took courage.'),
  ('6f3c3892-178d-5044-a96c-34053241984b', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 16, 16, 'When we entered into Rome, the centurion delivered the prisoners to the captain of the guard, but Paul was allowed to stay by himself with the soldier who guarded him.'),
  ('876063bf-9923-5f9d-a239-aff0e3d7c14c', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 17, 17, 'It happened that after three days Paul called together those who were the leaders of the Jews. When they had come together, he said to them, "I, brothers, though I had done nothing against the people, or the customs of our fathers, still was delivered prisoner from Jerusalem into the hands of the Romans,'),
  ('f784b2f4-b1d8-5db6-ab7d-34e875d5f3d5', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 18, 18, 'who, when they had examined me, desired to set me free, because there was no cause of death in me.'),
  ('401e07ed-93b5-5335-a2e6-4a99ebae44f0', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 19, 19, 'But when the Jews spoke against it, I was constrained to appeal to Caesar, not that I had anything about which to accuse my nation.'),
  ('9fd10c6f-7bff-56e6-a0be-923ddbf22f0a', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 20, 20, 'For this cause therefore I asked to see you and to speak with you. For because of the hope of Israel I am bound with this chain."'),
  ('6d491447-f1a9-5d8e-a2f0-f91f168005f1', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 21, 21, 'They said to him, "We neither received letters from Judea concerning you, nor did any of the brothers come here and report or speak any evil of you.'),
  ('9dabe381-dbd3-528b-aff1-905111ec54a0', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 22, 22, 'But we desire to hear from you what you think. For, as concerning this sect, it is known to us that everywhere it is spoken against."'),
  ('f2bcb7ec-1174-5c93-aded-2c4ccc3b42f5', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 23, 23, 'When they had appointed him a day, many people came to him at his lodging. He explained to them, testifying about the Kingdom of God, and persuading them concerning Jesus, both from the law of Moses and from the prophets, from morning until evening.'),
  ('ddde9e04-f3ff-5c35-a278-2b594c31605d', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 24, 24, 'Some believed the things which were spoken, and some disbelieved.'),
  ('eb9e1d54-1d86-561d-aa47-bfd84503f3c7', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 25, 25, 'When they didn''t agree among themselves, they departed after Paul had spoken one word, "The Holy Spirit spoke rightly through Isaiah, the prophet, to our fathers,'),
  ('7cf3bf40-335a-5156-ad25-2cadcfeb1e66', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 26, 26, 'saying, ''Go to this people, and say, in hearing, you will hear, but will in no way understand. In seeing, you will see, but will in no way perceive.'),
  ('bc115713-1a8b-5577-a45d-89ee7acdadbb', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 27, 27, 'For this people''s heart has grown callous. Their ears are dull of hearing. Their eyes they have closed. Lest they should see with their eyes, hear with their ears, understand with their heart, and would turn again, and I would heal them.'''),
  ('821d7b62-f1d7-586d-a825-913156254278', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 28, 28, '"Be it known therefore to you, that the salvation of God is sent to the nations. They will also listen."'),
  ('0f066c22-7530-5024-ab9c-f45840688a01', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 29, 29, 'When he had said these words, the Jews departed, having a great dispute among themselves.'),
  ('bc703ae0-00af-5c71-aa93-c56d0194961e', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 30, 30, 'Paul stayed two whole years in his own rented house, and received all who were coming to him,'),
  ('3266bad3-e26d-5755-a8db-1fdbe771a8dd', '53fbf055-e978-5b8e-a000-0a94eb4073aa', NULL, 31, 31, 'preaching the Kingdom of God, and teaching the things concerning the Lord Jesus Christ with all boldness, without hindrance.'),
  ('fcf725d6-1050-50a3-ac31-9c9c7ad62209', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 1, 1, 'Paul, a servant of Jesus Christ, called to be an apostle, set apart for the Good News of God,'),
  ('fd9d67f7-b8dd-5b42-a8c3-703cf1257bc2', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 2, 2, 'which he promised before through his prophets in the holy Scriptures,'),
  ('87da96ab-8789-520f-a746-103b696e6fd5', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 3, 3, 'concerning his Son, who was born of the seed of David according to the flesh,'),
  ('657ac62c-26e2-5d00-a6c1-58b54498d6cd', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 4, 4, 'who was declared to be the Son of God with power, according to the Spirit of holiness, by the resurrection from the dead, Jesus Christ our Lord,'),
  ('02660e31-3636-5aa2-ac11-b9531f3b0a02', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 5, 5, 'through whom we received grace and apostleship, for obedience of faith among all the nations, for his name''s sake;'),
  ('8d5af4c4-07d3-5fa3-a18c-411865559f91', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 6, 6, 'among whom you are also called to belong to Jesus Christ;'),
  ('1b11055c-0c55-5f4c-a560-95bb107e1fdb', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 7, 7, 'to all who are in Rome, beloved of God, called to be saints: Grace to you and peace from God our Father and the Lord Jesus Christ.'),
  ('71ab2ab0-4aa1-51bd-acce-31e45fa8ffba', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 8, 8, 'First, I thank my God through Jesus Christ for all of you, that your faith is proclaimed throughout the whole world.'),
  ('2543bbbb-81fd-57dd-a18a-a13730933dcb', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 9, 9, 'For God is my witness, whom I serve in my spirit in the Good News of his Son, how unceasingly I make mention of you always in my prayers,'),
  ('70f701f3-7553-5cfe-ae2d-cb2841358642', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 10, 10, 'requesting, if by any means now at last I may be prospered by the will of God to come to you.'),
  ('35f7f638-3dc3-5287-a736-a4e7b25fad3a', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 11, 11, 'For I long to see you, that I may impart to you some spiritual gift, to the end that you may be established;'),
  ('37260448-d6d7-5b8a-af66-6efe4552ebfd', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 12, 12, 'that is, that I with you may be encouraged in you, each of us by the other''s faith, both yours and mine.'),
  ('f4499268-ac3d-5bc8-a11b-5070a373ef6f', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 13, 13, 'Now I don''t desire to have you unaware, brothers, that I often planned to come to you, and was hindered so far, that I might have some fruit among you also, even as among the rest of the Gentiles.'),
  ('676069af-779c-5d01-ac8b-8b08f034ade8', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 14, 14, 'I am debtor both to Greeks and to foreigners, both to the wise and to the foolish.'),
  ('0d270ad3-b533-5c02-a7bf-d829892720c6', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 15, 15, 'So, as much as is in me, I am eager to preach the Good News to you also who are in Rome.'),
  ('ec8cdb24-a444-5c80-a691-a3c01ddd8370', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 16, 16, 'For I am not ashamed of the Good News of Christ, for it is the power of God for salvation for everyone who believes; for the Jew first, and also for the Greek.'),
  ('4b66fbbe-b676-50e2-a785-ea3693678a15', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 17, 17, 'For in it is revealed God''s righteousness from faith to faith. As it is written, "But the righteous shall live by faith."'),
  ('2a33439b-8f52-5b58-adab-7a968803a4ed', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 18, 18, 'For the wrath of God is revealed from heaven against all ungodliness and unrighteousness of men, who suppress the truth in unrighteousness,'),
  ('ef4c87fc-c290-5237-aac4-3a1beff411fc', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 19, 19, 'because that which is known of God is revealed in them, for God revealed it to them.'),
  ('c8fcf293-8857-57dc-ae72-50bb5b376858', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 20, 20, 'For the invisible things of him since the creation of the world are clearly seen, being perceived through the things that are made, even his everlasting power and divinity; that they may be without excuse.'),
  ('b4d6c8fa-d02e-5d8b-ac61-b7f3e7ab1990', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 21, 21, 'Because, knowing God, they didn''t glorify him as God, neither gave thanks, but became vain in their reasoning, and their senseless heart was darkened.'),
  ('74a5e0fd-bffb-5811-ae8a-ef72052abf4a', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 22, 22, 'Professing themselves to be wise, they became fools,'),
  ('34b9bec1-3781-5cb4-aa66-39504372f7c0', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 23, 23, 'and traded the glory of the incorruptible God for the likeness of an image of corruptible man, and of birds, and four-footed animals, and creeping things.'),
  ('ddb6c2ee-a8bf-5c3e-aa1f-b8d2947f692d', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 24, 24, 'Therefore God also gave them up in the lusts of their hearts to uncleanness, that their bodies should be dishonored among themselves,'),
  ('a04f4333-ab29-52da-acb1-6830d61b2541', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 25, 25, 'who exchanged the truth of God for a lie, and worshiped and served the creature rather than the Creator, who is blessed forever. Amen.'),
  ('64270957-ba83-55e9-a2b8-6e13028f34a3', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 26, 26, 'For this reason, God gave them up to vile passions. For their women changed the natural function into that which is against nature.'),
  ('1702a5b9-d0d9-5c8a-a440-8efdff57d90d', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 27, 27, 'Likewise also the men, leaving the natural function of the woman, burned in their lust toward one another, men doing what is inappropriate with men, and receiving in themselves the due penalty of their error.'),
  ('a4627726-c93f-51e8-a15c-e66b4dbde4fb', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 28, 28, 'Even as they refused to have God in their knowledge, God gave them up to a reprobate mind, to do those things which are not fitting;'),
  ('3f6e51c8-68bf-563b-adc5-78e2c9366f50', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 29, 29, 'being filled with all unrighteousness, sexual immorality, wickedness, covetousness, malice; full of envy, murder, strife, deceit, evil habits, secret slanderers,'),
  ('a972e424-4b72-54f1-a02b-c6e4a97aef4c', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 30, 30, 'backbiters, hateful to God, insolent, haughty, boastful, inventors of evil things, disobedient to parents,'),
  ('1afa3110-3bc0-53ed-aa56-f00e13a3d30a', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 31, 31, 'without understanding, covenant breakers, without natural affection, unforgiving, unmerciful;'),
  ('7f9b323f-3d5c-502d-ab22-91aea08b5fab', 'd15c3aa1-e777-597c-a1e0-a1b6f9e969bd', NULL, 32, 32, 'who, knowing the ordinance of God, that those who practice such things are worthy of death, not only do the same, but also approve of those who practice them.'),
  ('a20f32c9-a5fc-56a2-ad92-968abe17c3d6', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 1, 1, 'Therefore you are without excuse, O man, whoever you are who judge. For in that which you judge another, you condemn yourself. For you who judge practice the same things.'),
  ('e2d7008d-e76e-57b5-acaf-d162fc048dcd', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 2, 2, 'We know that the judgment of God is according to truth against those who practice such things.'),
  ('25199768-0a6b-53db-a665-c33fea52eefe', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 3, 3, 'Do you think this, O man who judges those who practice such things, and do the same, that you will escape the judgment of God?'),
  ('3f06fcb4-62bb-57c0-aa76-eba30a824c22', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 4, 4, 'Or do you despise the riches of his goodness, forbearance, and patience, not knowing that the goodness of God leads you to repentance?'),
  ('c35ca0d0-40b7-5b05-a03a-8236d2327c3c', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 5, 5, 'But according to your hardness and unrepentant heart you are treasuring up for yourself wrath in the day of wrath, revelation, and of the righteous judgment of God;'),
  ('fa959191-1591-5757-a7ae-c402ad7fa2b6', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 6, 6, 'who "will pay back to everyone according to their works:"'),
  ('e2a995ae-52be-5309-a5f1-c6e79e9d0a52', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 7, 7, 'to those who by patience in well-doing seek for glory, honor, and incorruptibility, eternal life;'),
  ('5aca030b-9c99-5768-ac50-552f24b06747', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 8, 8, 'but to those who are self-seeking, and don''t obey the truth, but obey unrighteousness, will be wrath and indignation,'),
  ('1b38f4c3-9594-5d74-acb1-351f4a4b257e', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 9, 9, 'oppression and anguish, on every soul of man who works evil, to the Jew first, and also to the Greek.'),
  ('bb4c9610-a310-5363-a89b-40974b7c2d11', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 10, 10, 'But glory, honor, and peace go to every man who works good, to the Jew first, and also to the Greek.'),
  ('c86bc3a9-2784-56e5-afe6-e9906976e98d', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 11, 11, 'For there is no partiality with God.'),
  ('75448822-b744-5ca2-a7ae-937da763c42c', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 12, 12, 'For as many as have sinned without law will also perish without the law. As many as have sinned under the law will be judged by the law.'),
  ('8b5e4aea-2b88-58ec-a958-386aeda6158b', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 13, 13, 'For it isn''t the hearers of the law who are righteous before God, but the doers of the law will be justified'),
  ('0dd4ee9f-ac70-594a-ab95-8d37a2e419dd', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 14, 14, '(for when Gentiles who don''t have the law do by nature the things of the law, these, not having the law, are a law to themselves,'),
  ('77853363-8014-5f66-a190-749ec61ddfb7', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 15, 15, 'in that they show the work of the law written in their hearts, their conscience testifying with them, and their thoughts among themselves accusing or else excusing them)'),
  ('6384d1e5-e819-5641-a528-28a4070fa4d0', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 16, 16, 'in the day when God will judge the secrets of men, according to my Good News, by Jesus Christ.'),
  ('1937252a-c730-5eb8-a6f3-48047eadab82', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 17, 17, 'Indeed you bear the name of a Jew, and rest on the law, and glory in God,'),
  ('9bcfe3bb-7eb8-5686-ac4c-2ab398d3d8ec', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 18, 18, 'and know his will, and approve the things that are excellent, being instructed out of the law,'),
  ('1abda88d-c813-597a-a0a5-3872683cd1b4', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 19, 19, 'and are confident that you yourself are a guide of the blind, a light to those who are in darkness,'),
  ('9d91b039-098b-55f1-a54a-1b06ebee7cfc', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 20, 20, 'a corrector of the foolish, a teacher of babies, having in the law the form of knowledge and of the truth.'),
  ('e6073871-71d2-51aa-a6db-c09879abc9a1', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 21, 21, 'You therefore who teach another, don''t you teach yourself? You who preach that a man shouldn''t steal, do you steal?'),
  ('5abcb433-098a-5586-abde-b6b5f012a957', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 22, 22, 'You who say a man shouldn''t commit adultery. Do you commit adultery? You who abhor idols, do you rob temples?'),
  ('c47a5ed2-506c-533c-a871-faddfc5fef7b', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 23, 23, 'You who glory in the law, through your disobedience of the law do you dishonor God?'),
  ('4e8ed7f1-66d6-5783-a312-bc87bc9b0bbc', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 24, 24, 'For "the name of God is blasphemed among the Gentiles because of you," just as it is written.'),
  ('36abc5d8-d9d6-5382-a321-57bb8f999705', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 25, 25, 'For circumcision indeed profits, if you are a doer of the law, but if you are a transgressor of the law, your circumcision has become uncircumcision.'),
  ('2ae9b927-a9b1-59f4-a089-5ac24040b41f', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 26, 26, 'If therefore the uncircumcised keep the ordinances of the law, won''t his uncircumcision be accounted as circumcision?'),
  ('833e466a-fc62-5357-a459-cea5f46c60f7', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 27, 27, 'Won''t the uncircumcision which is by nature, if it fulfills the law, judge you, who with the letter and circumcision are a transgressor of the law?'),
  ('938e2ca7-4f00-5e59-a4ee-3774aebdd254', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 28, 28, 'For he is not a Jew who is one outwardly, neither is that circumcision which is outward in the flesh;'),
  ('db57caf1-7adb-51c8-aa75-ebae6e9bcbea', 'aceca94f-ab1d-55a2-a08f-6a101c4ba943', NULL, 29, 29, 'but he is a Jew who is one inwardly, and circumcision is that of the heart, in the spirit not in the letter; whose praise is not from men, but from God.'),
  ('d923e9c4-3afd-58c5-ac55-1e18437700b6', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 1, 1, 'Then what advantage does the Jew have? Or what is the profit of circumcision?'),
  ('259cd472-6278-5db4-a4a1-7fb914ed5a97', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 2, 2, 'Much in every way! Because first of all, they were entrusted with the oracles of God.'),
  ('7956bf59-4a4f-58bf-ab15-71a0b6a24964', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 3, 3, 'For what if some were without faith? Will their lack of faith nullify the faithfulness of God?'),
  ('c8b1b040-6430-54c2-ae65-ebec8e10ffa8', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 4, 4, 'May it never be! Yes, let God be found true, but every man a liar. As it is written, "That you might be justified in your words, and might prevail when you come into judgment."'),
  ('4650cbdf-99fe-55a4-a0c0-9dbfc5470157', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 5, 5, 'But if our unrighteousness commends the righteousness of God, what will we say? Is God unrighteous who inflicts wrath? I speak like men do.'),
  ('6a79b2ea-9782-5806-a9bc-59702c3e9553', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 6, 6, 'May it never be! For then how will God judge the world?'),
  ('faac1ae4-70be-57aa-a4e7-de0d9c26f787', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 7, 7, 'For if the truth of God through my lie abounded to his glory, why am I also still judged as a sinner?'),
  ('41f37882-8fd3-5505-aa18-d3fb344d882f', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 8, 8, 'Why not (as we are slanderously reported, and as some affirm that we say), "Let us do evil, that good may come?" Those who say so are justly condemned.'),
  ('63015350-acc0-563d-a965-9d85d8d20ef0', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 9, 9, 'What then? Are we better than they? No, in no way. For we previously warned both Jews and Greeks, that they are all under sin.'),
  ('0a869e00-19f9-5707-a354-1153b33e9db2', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 10, 10, 'As it is written, "There is no one righteous; no, not one.'),
  ('ea8ce364-a55b-59dc-aba7-7fe24f85f8cc', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 11, 11, 'There is no one who understands. There is no one who seeks after God.'),
  ('042c4112-028b-5573-acdf-cb67750941ae', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 12, 12, 'They have all turned aside. They have together become unprofitable. There is no one who does good, no, not, so much as one."'),
  ('51763790-0700-5e80-af1d-e76a217b3fbb', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 13, 13, '"Their throat is an open tomb. With their tongues they have used deceit." "The poison of vipers is under their lips;"'),
  ('433e3782-aa2a-53bb-a79b-4220b213bc00', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 14, 14, '"whose mouth is full of cursing and bitterness."'),
  ('224f2006-bf0e-5857-ae6a-8b18f74e4c79', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 15, 15, '"Their feet are swift to shed blood.'),
  ('6f05075d-f42c-5f99-aa88-540fdb8a9ab6', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 16, 16, 'Destruction and misery are in their ways.'),
  ('7d871269-9bd6-59c6-a0c7-5bc2566fe381', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 17, 17, 'The way of peace, they haven''t known."'),
  ('c01f176b-00c3-5eba-a366-52dda703add6', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 18, 18, '"There is no fear of God before their eyes."'),
  ('ed62f50c-4e56-5052-ad26-865439046bc6', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 19, 19, 'Now we know that whatever things the law says, it speaks to those who are under the law, that every mouth may be closed, and all the world may be brought under the judgment of God.'),
  ('5dfcc9cd-73e7-5900-a4dc-8e8b7aa108e2', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 20, 20, 'Because by the works of the law, no flesh will be justified in his sight. For through the law comes the knowledge of sin.'),
  ('0edd77d9-17e0-5d9c-a9ad-c1d476259e4c', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 21, 21, 'But now apart from the law, a righteousness of God has been revealed, being testified by the law and the prophets;'),
  ('936c08d5-03d2-5f9a-af62-6eefdfbbebc3', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 22, 22, 'even the righteousness of God through faith in Jesus Christ to all and on all those who believe. For there is no distinction,'),
  ('bc3f9e73-0d8c-5b61-a077-b2de474cf132', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 23, 23, 'for all have sinned, and fall short of the glory of God;'),
  ('dd35f694-6f1a-584f-aff3-7828519ebf19', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 24, 24, 'being justified freely by his grace through the redemption that is in Christ Jesus;'),
  ('ccdfc592-90ee-5b4d-a3df-290a927fde51', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 25, 25, 'whom God set forth to be an atoning sacrifice, through faith in his blood, for a demonstration of his righteousness through the passing over of prior sins, in God''s forbearance;'),
  ('18aac4d0-26e3-5669-ac05-2e77835b81b2', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 26, 26, 'to demonstrate his righteousness at this present time; that he might himself be just, and the justifier of him who has faith in Jesus.'),
  ('08c2caac-2b97-5964-a185-13fddabe4328', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 27, 27, 'Where then is the boasting? It is excluded. By what kind of law? Of works? No, but by a law of faith.'),
  ('59af96c7-33d5-5ad8-a362-9c4bb7997bf6', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 28, 28, 'We maintain therefore that a man is justified by faith apart from the works of the law.'),
  ('cfc589ae-90c9-5d22-a04d-39c35f3a66c9', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 29, 29, 'Or is God the God of Jews only? Isn''t he the God of Gentiles also? Yes, of Gentiles also,'),
  ('e52e7be0-9248-5dc8-a627-b6c9d2d593eb', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 30, 30, 'since indeed there is one God who will justify the circumcised by faith, and the uncircumcised through faith.'),
  ('019344f4-7e81-530b-ac8b-c2064fcd78e6', '3863e8f5-8b07-5f4f-a5c1-aafdb307636c', NULL, 31, 31, 'Do we then nullify the law through faith? May it never be! No, we establish the law.'),
  ('0429d762-5a00-55eb-a82f-5ad92e2485e9', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 1, 1, 'What then will we say that Abraham, our forefather, has found according to the flesh?'),
  ('a0f65254-1b27-57eb-a499-31be8c8c90e4', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 2, 2, 'For if Abraham was justified by works, he has something to boast about, but not toward God.'),
  ('008017c3-4d86-5299-a60d-9a3fc0970c66', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 3, 3, 'For what does the Scripture say? "Abraham believed God, and it was accounted to him for righteousness."'),
  ('8ddfb83f-2bff-5104-a922-2e550f95b698', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 4, 4, 'Now to him who works, the reward is not counted as grace, but as something owed.'),
  ('15143f11-61f3-59cb-aabc-40c35e83d551', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 5, 5, 'But to him who doesn''t work, but believes in him who justifies the ungodly, his faith is accounted for righteousness.'),
  ('a9ea66ae-7da6-509a-af74-55dbf061b5ea', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 6, 6, 'Even as David also pronounces blessing on the man to whom God counts righteousness apart from works,'),
  ('6f51abb8-6eae-5c97-ad26-7d6412817181', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 7, 7, '"Blessed are they whose iniquities are forgiven, whose sins are covered.'),
  ('5132336d-4966-5f26-a127-c96cacfaed9a', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 8, 8, 'Blessed is the man whom the Lord will by no means charge with sin."'),
  ('38614169-40de-5b8f-a69f-5314b77c9ec4', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 9, 9, 'Is this blessing then pronounced on the circumcised, or on the uncircumcised also? For we say that faith was accounted to Abraham for righteousness.'),
  ('c4eab974-f977-5bd5-af07-e89a898911c4', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 10, 10, 'How then was it counted? When he was in circumcision, or in uncircumcision? Not in circumcision, but in uncircumcision.'),
  ('2c14804a-0d07-51da-afb9-511ff512571e', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 11, 11, 'He received the sign of circumcision, a seal of the righteousness of the faith which he had while he was in uncircumcision, that he might be the father of all those who believe, though they might be in uncircumcision, that righteousness might also be accounted to them.'),
  ('5201f716-9af8-57de-ac23-ed4e2f69fc50', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 12, 12, 'He is the father of circumcision to those who not only are of the circumcision, but who also walk in the steps of that faith of our father Abraham, which he had in uncircumcision.'),
  ('c493fef7-fd18-5ab3-a015-f175f3d7be71', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 13, 13, 'For the promise to Abraham and to his seed that he should be heir of the world wasn''t through the law, but through the righteousness of faith.'),
  ('c96d959b-ddad-5e71-a08b-2b94d99d097f', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 14, 14, 'For if those who are of the law are heirs, faith is made void, and the promise is made of no effect.'),
  ('a2053aec-fe27-5a33-aac3-0e9020bd6d89', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 15, 15, 'For the law works wrath, for where there is no law, neither is there disobedience.'),
  ('78208b02-22d3-5e1a-a2a8-4a94c89bab4c', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 16, 16, 'For this cause it is of faith, that it may be according to grace, to the end that the promise may be sure to all the seed, not to that only which is of the law, but to that also which is of the faith of Abraham, who is the father of us all.'),
  ('435225c2-713d-5029-a3f3-16d428c5df51', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 17, 17, 'As it is written, "I have made you a father of many nations." This is in the presence of him whom he believed: God, who gives life to the dead, and calls the things that are not, as though they were.'),
  ('05e16c11-4986-53b2-a1e9-63d4e2c883b0', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 18, 18, 'Who in hope believed against hope, to the end that he might become a father of many nations, according to that which had been spoken, "So will your seed be."'),
  ('ec3e03ee-5b74-5bac-abbd-7964b5598958', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 19, 19, 'Without being weakened in faith, he didn''t consider his own body, already having been worn out, (he being about a hundred years old), and the deadness of Sarah''s womb.'),
  ('b79e3b51-9dfa-5113-a2ab-dafe88e08d49', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 20, 20, 'Yet, looking to the promise of God, he didn''t waver through unbelief, but grew strong through faith, giving glory to God,'),
  ('02237c37-6e74-5c5c-a744-918db7cf6c03', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 21, 21, 'and being fully assured that what he had promised, he was also able to perform.'),
  ('004a6c5c-5c2e-5c20-a75b-93158fd64168', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 22, 22, 'Therefore it also was "reckoned to him for righteousness."'),
  ('bcc18e51-5c02-5780-a7c4-99f227c8b14e', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 23, 23, 'Now it was not written that it was accounted to him for his sake alone,'),
  ('d96a2d9a-b603-54d8-aa73-187465affc88', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 24, 24, 'but for our sake also, to whom it will be accounted, who believe in him who raised Jesus, our Lord, from the dead,'),
  ('894776ac-358e-5acc-a07b-f0f0e66460d6', 'c6d745cd-01e5-52fc-a056-7a425364f62c', NULL, 25, 25, 'who was delivered up for our trespasses, and was raised for our justification.'),
  ('312dc61c-e156-5793-a5ef-24b7a389dfc0', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 1, 1, 'Being therefore justified by faith, we have peace with God through our Lord Jesus Christ;'),
  ('ee6af06c-d791-5d76-a428-afedacd5880f', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 2, 2, 'through whom we also have our access by faith into this grace in which we stand. We rejoice in hope of the glory of God.'),
  ('6c0c9c3f-7a24-5ee9-a3b7-e2bb1f64a00f', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 3, 3, 'Not only this, but we also rejoice in our sufferings, knowing that suffering works perseverance;'),
  ('8f4ac7c8-856d-50b8-aedf-48cc855704a0', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 4, 4, 'and perseverance, proven character; and proven character, hope:'),
  ('cb6847e7-c591-5111-a51b-0d5aaea26f21', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 5, 5, 'and hope doesn''t disappoint us, because God''s love has been poured out into our hearts through the Holy Spirit who was given to us.'),
  ('32fa7248-7e04-5160-abbd-33ca2da1d3b2', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 6, 6, 'For while we were yet weak, at the right time Christ died for the ungodly.'),
  ('f7b0c82c-00a7-5ae5-a567-3d86f6aeeb50', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 7, 7, 'For one will hardly die for a righteous man. Yet perhaps for a righteous person someone would even dare to die.'),
  ('0f48da99-4fb2-5255-a98b-d0119dad1039', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 8, 8, 'But God commends his own love toward us, in that while we were yet sinners, Christ died for us.'),
  ('2041c8fd-e325-56c1-ae34-04ab9ae50286', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 9, 9, 'Much more then, being now justified by his blood, we will be saved from God''s wrath through him.'),
  ('549c2c0a-e830-5e4d-ac0b-8b022f5af929', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 10, 10, 'For if, while we were enemies, we were reconciled to God through the death of his Son, much more, being reconciled, we will be saved by his life.'),
  ('6822da63-91c2-5472-ab8a-b8ba1718d8e1', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 11, 11, 'Not only so, but we also rejoice in God through our Lord Jesus Christ, through whom we have now received the reconciliation.'),
  ('29788403-1ed1-5da8-a7d3-c2f994a7e8f7', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 12, 12, 'Therefore, as sin entered into the world through one man, and death through sin; and so death passed to all men, because all sinned.'),
  ('f3475298-ef87-5ab0-a9c9-70e9b12e4148', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 13, 13, 'For until the law, sin was in the world; but sin is not charged when there is no law.'),
  ('1af10a87-fd87-5dbf-a736-666297167e35', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 14, 14, 'Nevertheless death reigned from Adam until Moses, even over those whose sins weren''t like Adam''s disobedience, who is a foreshadowing of him who was to come.'),
  ('c6672544-1514-528c-a8fb-cd9c24a50b77', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 15, 15, 'But the free gift isn''t like the trespass. For if by the trespass of the one the many died, much more did the grace of God, and the gift by the grace of the one man, Jesus Christ, abound to the many.'),
  ('09ddeaab-d951-5d2b-a626-7ef3b1b53876', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 16, 16, 'The gift is not as through one who sinned: for the judgment came by one to condemnation, but the free gift came of many trespasses to justification.'),
  ('85fa52f6-d99c-531f-a40c-0a735433b375', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 17, 17, 'For if by the trespass of the one, death reigned through the one; so much more will those who receive the abundance of grace and of the gift of righteousness reign in life through the one, Jesus Christ.'),
  ('13afb82b-e206-5855-a81f-51e474e7a353', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 18, 18, 'So then as through one trespass, all men were condemned; even so through one act of righteousness, all men were justified to life.'),
  ('efa90fb1-0d1f-5aa5-ad33-b0a5ffe5ca69', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 19, 19, 'For as through the one man''s disobedience many were made sinners, even so through the obedience of the one, many will be made righteous.'),
  ('012ff03d-ba7e-5b38-a593-8da9ab7b5293', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 20, 20, 'The law came in besides, that the trespass might abound; but where sin abounded, grace abounded more exceedingly;'),
  ('43cb5f18-76d5-5fda-a967-aca21cd44d83', '93dde671-7e51-5593-a1e2-87ff36777cef', NULL, 21, 21, 'that as sin reigned in death, even so grace might reign through righteousness to eternal life through Jesus Christ our Lord.'),
  ('e04d52f5-46cd-5d9e-ab02-f2940d11a84c', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 1, 1, 'What shall we say then? Shall we continue in sin, that grace may abound?'),
  ('ef76b536-0db2-56b4-aa71-fbf47557a9fe', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 2, 2, 'May it never be! We who died to sin, how could we live in it any longer?'),
  ('59429b5f-8b06-528b-a2bd-8e96e51031e5', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 3, 3, 'Or don''t you know that all we who were baptized into Christ Jesus were baptized into his death?'),
  ('6adca60f-5b63-531c-ad0b-38237fd82768', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 4, 4, 'We were buried therefore with him through baptism to death, that just like Christ was raised from the dead through the glory of the Father, so we also might walk in newness of life.'),
  ('6cf74358-0a7f-5d0b-a242-0058fc9b3d91', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 5, 5, 'For if we have become united with him in the likeness of his death, we will also be part of his resurrection;'),
  ('168bf72a-5c57-58a4-a7d2-172c5d7b374d', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 6, 6, 'knowing this, that our old man was crucified with him, that the body of sin might be done away with, so that we would no longer be in bondage to sin.'),
  ('57bd7167-e2e6-5421-a2d8-2d5037fd76ce', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 7, 7, 'For he who has died has been freed from sin.'),
  ('b9d003c9-874b-5406-a35c-97fed5a23ba1', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 8, 8, 'But if we died with Christ, we believe that we will also live with him;'),
  ('31cbbe06-796c-524b-a164-b51054f60d82', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 9, 9, 'knowing that Christ, being raised from the dead, dies no more. Death no more has dominion over him!'),
  ('5bd9b377-b54e-578b-a146-e0ab783c0899', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 10, 10, 'For the death that he died, he died to sin one time; but the life that he lives, he lives to God.'),
  ('da9e0147-3793-5245-afd1-61f364193d7c', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 11, 11, 'Thus consider yourselves also to be dead to sin, but alive to God in Christ Jesus our Lord.'),
  ('be5de2a6-0d70-54ab-a9d1-ca987ae6fec4', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 12, 12, 'Therefore don''t let sin reign in your mortal body, that you should obey it in its lusts.'),
  ('0ecb2239-ec89-57cf-aa7d-729dbbdf48f3', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 13, 13, 'Neither present your members to sin as instruments of unrighteousness, but present yourselves to God, as alive from the dead, and your members as instruments of righteousness to God.'),
  ('64786d8d-bc7a-5091-af3a-9cb4236a5326', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 14, 14, 'For sin will not have dominion over you. For you are not under law, but under grace.'),
  ('64b991c9-9e7d-55a8-a0d8-3ace5593beb0', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 15, 15, 'What then? Shall we sin, because we are not under law, but under grace? May it never be!'),
  ('0c2b066d-6d37-5777-ac41-40b4f841d8e7', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 16, 16, 'Don''t you know that to whom you present yourselves as servants to obedience, his servants you are whom you obey; whether of sin to death, or of obedience to righteousness?'),
  ('19678a80-7701-5476-a1da-081f41514f65', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 17, 17, 'But thanks be to God, that, whereas you were bondservants of sin, you became obedient from the heart to that form of teaching whereunto you were delivered.'),
  ('2bfe8635-5047-5980-ae2c-30b0c74951c2', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 18, 18, 'Being made free from sin, you became bondservants of righteousness.'),
  ('64ef8d4b-70b3-556e-a93d-c320a38b4382', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 19, 19, 'I speak in human terms because of the weakness of your flesh, for as you presented your members as servants to uncleanness and to wickedness upon wickedness, even so now present your members as servants to righteousness for sanctification.'),
  ('9ce3b190-f983-52ce-ae71-ba4ca3174157', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 20, 20, 'For when you were servants of sin, you were free in regard to righteousness.'),
  ('f1500935-e89d-5073-aa9d-a3170a512db0', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 21, 21, 'What fruit then did you have at that time in the things of which you are now ashamed? For the end of those things is death.'),
  ('a3913517-b1da-563c-a3ac-051fd539ab66', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 22, 22, 'But now, being made free from sin, and having become servants of God, you have your fruit of sanctification, and the result of eternal life.'),
  ('915290bb-bbd5-5e99-ae95-77310bf8830a', '688b360b-59eb-5907-a950-d8ae40b6b210', NULL, 23, 23, 'For the wages of sin is death, but the free gift of God is eternal life in Christ Jesus our Lord.'),
  ('3c02f539-d77a-511a-a70c-90b45b66a7be', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 1, 1, 'Or don''t you know, brothers (for I speak to men who know the law), that the law has dominion over a man for as long as he lives?'),
  ('0a0aa48b-a370-5aee-a45d-460768312d3e', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 2, 2, 'For the woman that has a husband is bound by law to the husband while he lives, but if the husband dies, she is discharged from the law of the husband.'),
  ('8b9b8923-a12c-5e66-a923-840c520112d4', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 3, 3, 'So then if, while the husband lives, she is joined to another man, she would be called an adulteress. But if the husband dies, she is free from the law, so that she is no adulteress, though she is joined to another man.'),
  ('02ed6671-cc96-527d-adb8-3848fb7f03a4', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 4, 4, 'Therefore, my brothers, you also were made dead to the law through the body of Christ, that you would be joined to another, to him who was raised from the dead, that we might bring forth fruit to God.'),
  ('6d269347-001e-520d-a613-61fdbcad1ae3', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 5, 5, 'For when we were in the flesh, the sinful passions which were through the law, worked in our members to bring forth fruit to death.'),
  ('01bd953a-0a00-56bc-a37f-b1085fdfc6da', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 6, 6, 'But now we have been discharged from the law, having died to that in which we were held; so that we serve in newness of the spirit, and not in oldness of the letter.'),
  ('de36b967-9603-5227-a201-28c9fd57f928', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 7, 7, 'What shall we say then? Is the law sin? May it never be! However, I wouldn''t have known sin, except through the law. For I wouldn''t have known coveting, unless the law had said, "You shall not covet."'),
  ('a0102b54-e0d2-584a-a799-b35186d0fbd0', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 8, 8, 'But sin, finding occasion through the commandment, produced in me all kinds of coveting. For apart from the law, sin is dead.'),
  ('a2e27b88-edcb-57b5-a922-a15ba2e51cb5', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 9, 9, 'I was alive apart from the law once, but when the commandment came, sin revived, and I died.'),
  ('2f4810ce-7930-5f73-ac8e-aa958ddb7f3d', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 10, 10, 'The commandment, which was for life, this I found to be for death;'),
  ('e2a66b82-b691-58aa-ac54-3998bc05afd2', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 11, 11, 'for sin, finding occasion through the commandment, deceived me, and through it killed me.'),
  ('e2e3242d-8c0c-5f43-ac62-770611d750be', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 12, 12, 'Therefore the law indeed is holy, and the commandment holy, and righteous, and good.'),
  ('172cdd03-bfdb-5040-ae39-5b2a2ecb4d6c', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 13, 13, 'Did then that which is good become death to me? May it never be! But sin, that it might be shown to be sin, by working death to me through that which is good; that through the commandment sin might become exceeding sinful.'),
  ('bfc05ac3-636c-55de-a4a1-ba0939d284c9', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 14, 14, 'For we know that the law is spiritual, but I am fleshly, sold under sin.'),
  ('2d648a48-53eb-573c-a056-3741993d7944', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 15, 15, 'For I don''t know what I am doing. For I don''t practice what I desire to do; but what I hate, that I do.'),
  ('5baf13d8-80a4-5125-ae43-9a51a6ca2515', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 16, 16, 'But if what I don''t desire, that I do, I consent to the law that it is good.'),
  ('fb77f439-21f6-532a-a18c-df9d6d832fed', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 17, 17, 'So now it is no more I that do it, but sin which dwells in me.'),
  ('825a45d7-b2dc-5ff2-aaca-a747881b4b09', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 18, 18, 'For I know that in me, that is, in my flesh, dwells no good thing. For desire is present with me, but I don''t find it doing that which is good.'),
  ('760b1959-1382-5550-a929-2e20c8e563c9', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 19, 19, 'For the good which I desire, I don''t do; but the evil which I don''t desire, that I practice.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2a91d789-e1d6-56e6-a1cb-0f877f2cbdf0', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 20, 20, 'But if what I don''t desire, that I do, it is no more I that do it, but sin which dwells in me.'),
  ('3c204940-43b3-547e-ad6d-6aa38a590b55', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 21, 21, 'I find then the law, that, to me, while I desire to do good, evil is present.'),
  ('57c5efcc-6e7b-5783-af8e-e6d8db8b1999', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 22, 22, 'For I delight in God''s law after the inward man,'),
  ('a90d6fbe-96ec-5095-a48b-a9604edcafef', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 23, 23, 'but I see a different law in my members, warring against the law of my mind, and bringing me into captivity under the law of sin which is in my members.'),
  ('39519b2a-e746-5941-a341-f68d626f16f8', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 24, 24, 'What a wretched man I am! Who will deliver me out of the body of this death?'),
  ('e819021f-185c-5b11-aadc-323eb0559579', '0d454352-a498-5088-ab70-a731b4376d9d', NULL, 25, 25, 'I thank God through Jesus Christ, our Lord! So then with the mind, I myself serve God''s law, but with the flesh, the sin''s law.'),
  ('7d0e3ef3-fb10-5c08-a5ec-d1a2f903bc02', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 1, 1, 'There is therefore now no condemnation to those who are in Christ Jesus, who don''t walk according to the flesh, but according to the Spirit.'),
  ('589380fd-0ecb-5249-a214-7815e880738a', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 2, 2, 'For the law of the Spirit of life in Christ Jesus made me free from the law of sin and of death.'),
  ('397699b4-a7b4-501b-aeae-a52c0b679132', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 3, 3, 'For what the law couldn''t do, in that it was weak through the flesh, God did, sending his own Son in the likeness of sinful flesh and for sin, he condemned sin in the flesh;'),
  ('e5e960a2-93c5-58bf-af51-860960fbde7e', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 4, 4, 'that the ordinance of the law might be fulfilled in us, who walk not after the flesh, but after the Spirit.'),
  ('f8aeb672-9ac6-5083-a094-2090ca93f075', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 5, 5, 'For those who live according to the flesh set their minds on the things of the flesh, but those who live according to the Spirit, the things of the Spirit.'),
  ('4dfff34c-88d7-5006-a2c4-f51f7a620093', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 6, 6, 'For the mind of the flesh is death, but the mind of the Spirit is life and peace;'),
  ('694e6add-93db-5eec-a323-8f2345a13f2d', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 7, 7, 'because the mind of the flesh is hostile towards God; for it is not subject to God''s law, neither indeed can it be.'),
  ('ce93ecad-79f7-59dc-a741-952450c3618e', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 8, 8, 'Those who are in the flesh can''t please God.'),
  ('efa994a1-96c6-5cc2-ad39-9664d787e3ac', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 9, 9, 'But you are not in the flesh but in the Spirit, if it is so that the Spirit of God dwells in you. But if any man doesn''t have the Spirit of Christ, he is not his.'),
  ('ef54ba11-b8c4-5001-a76f-e438755cd1a4', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 10, 10, 'If Christ is in you, the body is dead because of sin, but the spirit is alive because of righteousness.'),
  ('a716e294-3f16-57e1-ad46-9b2c64f8851c', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 11, 11, 'But if the Spirit of him who raised up Jesus from the dead dwells in you, he who raised up Christ Jesus from the dead will also give life to your mortal bodies through his Spirit who dwells in you.'),
  ('a29c0d60-7031-59fb-a055-f00adf43b5ad', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 12, 12, 'So then, brothers, we are debtors, not to the flesh, to live after the flesh.'),
  ('9f1731c2-e523-52ef-a2b0-8a61b051adc4', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 13, 13, 'For if you live after the flesh, you must die; but if by the Spirit you put to death the deeds of the body, you will live.'),
  ('41d64079-68aa-5fb5-a4e0-baf94485cb86', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 14, 14, 'For as many as are led by the Spirit of God, these are children of God.'),
  ('1c3bbaec-20bf-56de-a2bd-70272d048ff9', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 15, 15, 'For you didn''t receive the spirit of bondage again to fear, but you received the Spirit of adoption, by whom we cry, "Abba! Father!"'),
  ('29716e0a-29f7-5a02-a9e9-de8ec5074d3b', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 16, 16, 'The Spirit himself testifies with our spirit that we are children of God;'),
  ('bf93930f-0403-5120-a88b-5fa93c1c9ad4', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 17, 17, 'and if children, then heirs; heirs of God, and joint heirs with Christ; if indeed we suffer with him, that we may also be glorified with him.'),
  ('d5fa3e3c-9322-52b2-afd8-ebe08b6d732f', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 18, 18, 'For I consider that the sufferings of this present time are not worthy to be compared with the glory which will be revealed toward us.'),
  ('0e294477-9716-522b-a6f7-a5449e0d06cc', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 19, 19, 'For the creation waits with eager expectation for the children of God to be revealed.'),
  ('08b33f2a-84f7-587e-ae83-91feda14867e', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 20, 20, 'For the creation was subjected to vanity, not of its own will, but because of him who subjected it, in hope'),
  ('cbda26f8-c9bc-55ab-ae9c-11eab1b01751', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 21, 21, 'that the creation itself also will be delivered from the bondage of decay into the liberty of the glory of the children of God.'),
  ('38583ae4-6c01-5214-a114-7a2029a6418d', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 22, 22, 'For we know that the whole creation groans and travails in pain together until now.'),
  ('d016133a-83d2-5031-af6c-2db804e24ddb', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 23, 23, 'Not only so, but ourselves also, who have the first fruits of the Spirit, even we ourselves groan within ourselves, waiting for adoption, the redemption of our body.'),
  ('d95a8d5f-1754-5476-aab5-d7f12a8df0af', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 24, 24, 'For we were saved in hope, but hope that is seen is not hope. For who hopes for that which he sees?'),
  ('1874e093-a17b-5801-a03f-e78d58e3de89', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 25, 25, 'But if we hope for that which we don''t see, we wait for it with patience.'),
  ('265e36e8-da9d-5078-a81a-c25929b57a98', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 26, 26, 'In the same way, the Spirit also helps our weaknesses, for we don''t know how to pray as we ought. But the Spirit himself makes intercession for us with groanings which can''t be uttered.'),
  ('490fea77-8f0e-5743-ad07-d632ff656472', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 27, 27, 'He who searches the hearts knows what is on the Spirit''s mind, because he makes intercession for the saints according to God.'),
  ('424c4aef-a130-5a6d-a543-e984de9779aa', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 28, 28, 'We know that all things work together for good for those who love God, to those who are called according to his purpose.'),
  ('2108695d-d3e0-58b0-acdf-a508cdc7779e', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 29, 29, 'For whom he foreknew, he also predestined to be conformed to the image of his Son, that he might be the firstborn among many brothers.'),
  ('ec00fa10-a101-5832-a79d-6255391fb782', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 30, 30, 'Whom he predestined, those he also called. Whom he called, those he also justified. Whom he justified, those he also glorified.'),
  ('b09a5199-e828-5599-a652-c0905a7c2f38', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 31, 31, 'What then shall we say about these things? If God is for us, who can be against us?'),
  ('5ef3cb2c-1d6e-55ea-aa61-3121139de55c', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 32, 32, 'He who didn''t spare his own Son, but delivered him up for us all, how would he not also with him freely give us all things?'),
  ('5dec82aa-22be-5305-a86f-f1593a483cd2', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 33, 33, 'Who could bring a charge against God''s chosen ones? It is God who justifies.'),
  ('fc418715-2126-5f0a-a7f7-6bfb3871b219', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 34, 34, 'Who is he who condemns? It is Christ who died, yes rather, who was raised from the dead, who is at the right hand of God, who also makes intercession for us.'),
  ('33bcb5b8-cfa4-57c3-a69d-ac555ca95d48', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 35, 35, 'Who shall separate us from the love of Christ? Could oppression, or anguish, or persecution, or famine, or nakedness, or peril, or sword?'),
  ('a3c88344-47ab-5ffe-abd8-fb60d00b4597', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 36, 36, 'Even as it is written, "For your sake we are killed all day long. We were accounted as sheep for the slaughter."'),
  ('cc00699d-2625-5f47-a871-e8ab829cc455', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 37, 37, 'No, in all these things, we are more than conquerors through him who loved us.'),
  ('7c63bf54-c19f-5b29-a9af-9774a3aed372', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 38, 38, 'For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor things present, nor things to come, nor powers,'),
  ('052cd3db-405e-522c-a5a7-62022308257d', '642515ee-4955-59bd-a770-7109e105a1ed', NULL, 39, 39, 'nor height, nor depth, nor any other created thing, will be able to separate us from the love of God, which is in Christ Jesus our Lord.'),
  ('ae3877b9-8a8b-52bd-afc2-eb9c1fe1e594', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 1, 1, 'I tell the truth in Christ. I am not lying, my conscience testifying with me in the Holy Spirit,'),
  ('4f11f7d6-22f3-5862-ae4b-3c7aa6d031b4', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 2, 2, 'that I have great sorrow and unceasing pain in my heart.'),
  ('f0691752-fc0f-5cec-a477-212252f07682', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 3, 3, 'For I could wish that I myself were accursed from Christ for my brothers'' sake, my relatives according to the flesh,'),
  ('bb6dbc48-9dc9-54b8-af65-90d0f6540e26', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 4, 4, 'who are Israelites; whose is the adoption, the glory, the covenants, the giving of the law, the service, and the promises;'),
  ('2476193c-245f-5122-aeb7-98bd4f6ba816', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 5, 5, 'of whom are the fathers, and from whom is Christ as concerning the flesh, who is over all, God, blessed forever. Amen.'),
  ('a8602746-5381-5ff9-aee9-f63874b7bf37', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 6, 6, 'But it is not as though the word of God has come to nothing. For they are not all Israel, that are of Israel.'),
  ('a0b8a102-6514-567a-afa4-5bc5e39fcf59', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 7, 7, 'Neither, because they are Abraham''s seed, are they all children. But, "In Isaac will your seed be called."'),
  ('3466248b-b9da-5dc5-a154-166334307be3', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 8, 8, 'That is, it is not the children of the flesh who are children of God, but the children of the promise are counted as a seed.'),
  ('8e3bb38a-01c7-5824-aaee-dd7796b0e491', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 9, 9, 'For this is a word of promise, "At the appointed time I will come, and Sarah will have a son."'),
  ('4816125b-8031-534b-aa19-79bb36fb8ea6', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 10, 10, 'Not only so, but Rebecca also conceived by one, by our father Isaac.'),
  ('7691ac8b-7fef-5590-a1e2-8672e28598d9', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 11, 11, 'For being not yet born, neither having done anything good or bad, that the purpose of God according to election might stand, not of works, but of him who calls,'),
  ('53d82a67-cdec-55eb-adf0-4962de1c8d8d', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 12, 12, 'it was said to her, "The elder will serve the younger."'),
  ('1476fe46-d48d-50f7-a30c-a7861c93ad64', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 13, 13, 'Even as it is written, "Jacob I loved, but Esau I hated."'),
  ('b8fd8d38-19e7-5627-a3f3-0d03264be9a3', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 14, 14, 'What shall we say then? Is there unrighteousness with God? May it never be!'),
  ('669f0786-17b2-5e9c-a341-6f1021bf0892', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 15, 15, 'For he said to Moses, "I will have mercy on whom I have mercy, and I will have compassion on whom I have compassion."'),
  ('93e56944-ce0a-57bf-a79d-d878463b6eda', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 16, 16, 'So then it is not of him who wills, nor of him who runs, but of God who has mercy.'),
  ('a91e1036-119f-5947-ad3b-42eba212b09f', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 17, 17, 'For the Scripture says to Pharaoh, "For this very purpose I caused you to be raised up, that I might show in you my power, and that my name might be proclaimed in all the earth."'),
  ('5d90649c-475c-57af-a398-4e234a274227', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 18, 18, 'So then, he has mercy on whom he desires, and he hardens whom he desires.'),
  ('ad38fda3-d363-5e4a-a96a-fb0af75dfc2e', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 19, 19, 'You will say then to me, "Why does he still find fault? For who withstands his will?"'),
  ('7b5aa146-ddd4-5c25-ac59-a819cec00da7', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 20, 20, 'But indeed, O man, who are you to reply against God? Will the thing formed ask him who formed it, "Why did you make me like this?"'),
  ('1441cbc2-9041-56f1-ace6-d08a5f2af045', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 21, 21, 'Or hasn''t the potter a right over the clay, from the same lump to make one part a vessel for honor, and another for dishonor?'),
  ('82d86df2-95ae-5def-aff7-e1fb7c74d055', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 22, 22, 'What if God, willing to show his wrath, and to make his power known, endured with much patience vessels of wrath made for destruction,'),
  ('b3058e5e-5dfb-5f9a-a43c-d3c7d5c5a90f', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 23, 23, 'and that he might make known the riches of his glory on vessels of mercy, which he prepared beforehand for glory,'),
  ('3c66713c-8da5-5f97-a333-e8a4b80dda2f', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 24, 24, 'us, whom he also called, not from the Jews only, but also from the Gentiles?'),
  ('45f3972e-21b6-5fbc-a0a5-1f6983a53ce4', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 25, 25, 'As he says also in Hosea, "I will call them ''my people,'' which were not my people; and her ''beloved,'' who was not beloved."'),
  ('860afc90-7c48-5413-ab0e-e0fb9b15ed50', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 26, 26, '"It will be that in the place where it was said to them, ''You are not my people,'' There they will be called ''children of the living God.''"'),
  ('df0c21e0-a621-5607-a2b4-337b6c6e3cc2', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 27, 27, 'Isaiah cries concerning Israel, "If the number of the children of Israel are as the sand of the sea, it is the remnant who will be saved;'),
  ('6c70fd3e-fa15-56f2-a753-06f71871d340', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 28, 28, 'for He will finish the work and cut it short in righteousness, because the LORD will make a short work upon the earth."'),
  ('a6e44416-5d7c-5580-a948-343dce95c36e', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 29, 29, 'As Isaiah has said before, "Unless the Lord of Armies had left us a seed, we would have become like Sodom, and would have been made like Gomorrah."'),
  ('4d09e0b3-77a6-529d-a540-bd685d916425', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 30, 30, 'What shall we say then? That the Gentiles, who didn''t follow after righteousness, attained to righteousness, even the righteousness which is of faith;'),
  ('7cca7124-446c-574b-a227-ab491d491b54', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 31, 31, 'but Israel, following after a law of righteousness, didn''t arrive at the law of righteousness.'),
  ('ac26ad06-c248-56d1-ab20-0f6916719d4d', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 32, 32, 'Why? Because they didn''t seek it by faith, but as it were by works of the law. They stumbled over the stumbling stone;'),
  ('9f35741e-db7f-5511-a780-7b0c8c432e18', '7a520cfb-f849-5fa8-a4ce-365bcc55ffdf', NULL, 33, 33, 'even as it is written, "Behold, I lay in Zion a stumbling stone and a rock of offense; and no one who believes in him will be disappointed."'),
  ('31295812-b092-50f5-a5bd-f2eb9379f335', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 1, 1, 'Brothers, my heart''s desire and my prayer to God is for Israel, that they may be saved.'),
  ('29b83ada-fef2-56a4-a5ae-f704cd961cca', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 2, 2, 'For I testify about them that they have a zeal for God, but not according to knowledge.'),
  ('f443f48f-3d30-55d5-ad68-317a635b4a33', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 3, 3, 'For being ignorant of God''s righteousness, and seeking to establish their own righteousness, they didn''t subject themselves to the righteousness of God.'),
  ('4d4d25ca-3378-58a4-af7f-2a937c7a5ec6', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 4, 4, 'For Christ is the fulfillment of the law for righteousness to everyone who believes.'),
  ('b16e1d6d-ff09-580a-abc5-37e563309e11', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 5, 5, 'For Moses writes about the righteousness of the law, "The one who does them will live by them."'),
  ('0fceeea9-f1d5-5418-a06a-8d90f1f52011', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 6, 6, 'But the righteousness which is of faith says this, "Don''t say in your heart, ''Who will ascend into heaven?'' (that is, to bring Christ down);'),
  ('abc2d12b-950f-5375-a48f-1fba7b034300', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 7, 7, 'or, ''Who will descend into the abyss?'' (that is, to bring Christ up from the dead.)"'),
  ('aad1adb3-88e9-5537-a8e7-a92b3e1b5fa8', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 8, 8, 'But what does it say? "The word is near you, in your mouth, and in your heart;" that is, the word of faith, which we preach:'),
  ('d93979b4-4533-5487-aaf9-729a976bac90', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 9, 9, 'that if you will confess with your mouth that Jesus is Lord, and believe in your heart that God raised him from the dead, you will be saved.'),
  ('eae690e3-3b09-5e34-a142-230e958dda81', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 10, 10, 'For with the heart, one believes unto righteousness; and with the mouth confession is made unto salvation.'),
  ('aeb59755-a287-53c9-a849-a22d80d09cf3', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 11, 11, 'For the Scripture says, "Whoever believes in him will not be disappointed."'),
  ('aed15f79-6c04-53ae-a8fb-735a66963e86', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 12, 12, 'For there is no distinction between Jew and Greek; for the same Lord is Lord of all, and is rich to all who call on him.'),
  ('d622b98b-bde2-50c8-a4c7-7912bb69e29c', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 13, 13, 'For, "Whoever will call on the name of the Lord will be saved."'),
  ('9eda8e90-4745-5748-a54b-4b4197bdfed4', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 14, 14, 'How then will they call on him in whom they have not believed? How will they believe in him whom they have not heard? How will they hear without a preacher?'),
  ('c31936bd-6546-519b-a387-a4d697c5d80a', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 15, 15, 'And how will they preach unless they are sent? As it is written: "How beautiful are the feet of those who preach the Good News of peace, who bring glad tidings of good things!"'),
  ('7b0d9174-0172-583d-a2a2-6b51cc011c47', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 16, 16, 'But they didn''t all listen to the glad news. For Isaiah says, "Lord, who has believed our report?"'),
  ('a9ff4c91-b340-5004-a84e-f004992a982d', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 17, 17, 'So faith comes by hearing, and hearing by the word of God.'),
  ('69be8c98-4510-5ace-a065-0f5b1b6617fc', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 18, 18, 'But I say, didn''t they hear? Yes, most certainly, "Their sound went out into all the earth, their words to the ends of the world."'),
  ('1fc5b9a7-1e09-5adf-ae7b-3258d59e2b26', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 19, 19, 'But I ask, didn''t Israel know? First Moses says, "I will provoke you to jealousy with that which is no nation, with a nation void of understanding I will make you angry."'),
  ('6a406310-a19e-5934-a963-51e3c164d174', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 20, 20, 'Isaiah is very bold, and says, "I was found by those who didn''t seek me. I was revealed to those who didn''t ask for me."'),
  ('640c1945-95c5-581c-ab88-ff0e442d5792', '37949ff1-5aac-5157-a44f-b4135ef15253', NULL, 21, 21, 'But as to Israel he says, "All day long I stretched out my hands to a disobedient and contrary people."'),
  ('af7223e9-df39-5d42-abf3-ff358ee6c6ae', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 1, 1, 'I ask then, did God reject his people? May it never be! For I also am an Israelite, a descendant of Abraham, of the tribe of Benjamin.'),
  ('4cad9422-b3ec-5256-adb7-9b70ef4f66cf', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 2, 2, 'God didn''t reject his people, which he foreknew. Or don''t you know what the Scripture says about Elijah? How he pleads with God against Israel:'),
  ('9f28a33f-15f9-57ba-a2e1-03776a69f7e5', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 3, 3, '"Lord, they have killed your prophets, they have broken down your altars; and I am left alone, and they seek my life."'),
  ('f0b534da-ccdf-5427-a65d-9dcfd65a3a31', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 4, 4, 'But how does God answer him? "I have reserved for myself seven thousand men, who have not bowed the knee to Baal."'),
  ('56451a2f-be8d-5e0d-a4e9-e19dc8d665e1', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 5, 5, 'Even so then at this present time also there is a remnant according to the election of grace.'),
  ('9cac0d21-56f9-5106-a00b-705a0d0c7019', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 6, 6, 'And if by grace, then it is no longer of works; otherwise grace is no longer grace. But if it is of works, it is no longer grace; otherwise work is no longer work.'),
  ('efa3f647-96ae-5878-a3d8-25902062472d', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 7, 7, 'What then? That which Israel seeks for, that he didn''t obtain, but the chosen ones obtained it, and the rest were hardened.'),
  ('d2239c50-f5f1-57b2-a50b-5012025eff7d', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 8, 8, 'According as it is written, "God gave them a spirit of stupor, eyes that they should not see, and ears that they should not hear, to this very day."'),
  ('242711e1-e568-5808-a10f-a7367d212b8e', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 9, 9, 'David says, "Let their table be made a snare, and a trap, a stumbling block, and a retribution to them.'),
  ('8272f109-4a20-5b10-ae38-3c0a99035401', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 10, 10, 'Let their eyes be darkened, that they may not see. Bow down their back always."'),
  ('3a24a66b-0d89-5938-ac3f-cd88f2510e43', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 11, 11, 'I ask then, did they stumble that they might fall? May it never be! But by their fall salvation has come to the Gentiles, to provoke them to jealousy.'),
  ('afffb0a1-1113-56b2-a14b-fb04a1890a65', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 12, 12, 'Now if their fall is the riches of the world, and their loss the riches of the Gentiles; how much more their fullness?'),
  ('7a1efd2d-5026-5139-a315-ce63e6104bae', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 13, 13, 'For I speak to you who are Gentiles. Since then as I am an apostle to Gentiles, I glorify my ministry;'),
  ('d3cf562a-5855-5a7a-a7c2-7dc6dae92687', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 14, 14, 'if by any means I may provoke to jealousy those who are my flesh, and may save some of them.'),
  ('056525c8-d0e3-5827-ad84-30fb92a4017e', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 15, 15, 'For if the rejection of them is the reconciling of the world, what would their acceptance be, but life from the dead?'),
  ('b1900f7f-ad35-5b52-ada5-1b12fa5dec1b', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 16, 16, 'If the first fruit is holy, so is the lump. If the root is holy, so are the branches.'),
  ('1f98d133-0b94-5ff9-af5f-c4337ee45e46', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 17, 17, 'But if some of the branches were broken off, and you, being a wild olive, were grafted in among them, and became partaker with them of the root and of the richness of the olive tree;'),
  ('dc2fa037-dd6b-5097-a599-54573ca4ea23', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 18, 18, 'don''t boast over the branches. But if you boast, it is not you who support the root, but the root supports you.'),
  ('a9a215dd-f517-509f-ab31-336a6eaa4627', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 19, 19, 'You will say then, "Branches were broken off, that I might be grafted in."'),
  ('34e0d347-b3db-5ee1-a3be-f5a7f2458064', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 20, 20, 'True; by their unbelief they were broken off, and you stand by your faith. Don''t be conceited, but fear;'),
  ('def1782c-97eb-528e-a370-344734f89d50', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 21, 21, 'for if God didn''t spare the natural branches, neither will he spare you.'),
  ('139082b7-173f-5572-a102-3ff2b6e6910d', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 22, 22, 'See then the goodness and severity of God. Toward those who fell, severity; but toward you, goodness, if you continue in his goodness; otherwise you also will be cut off.'),
  ('fa2ece71-6925-5dd5-af84-787cfb65c864', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 23, 23, 'They also, if they don''t continue in their unbelief, will be grafted in, for God is able to graft them in again.'),
  ('ecbd63bc-6c0c-5a70-afed-58372fabaca1', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 24, 24, 'For if you were cut out of that which is by nature a wild olive tree, and were grafted contrary to nature into a good olive tree, how much more will these, which are the natural branches, be grafted into their own olive tree?'),
  ('9c71f9a1-3bde-592a-a54a-8be8d7776631', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 25, 25, 'For I don''t desire you to be ignorant, brothers, of this mystery, so that you won''t be wise in your own conceits, that a partial hardening has happened to Israel, until the fullness of the Gentiles has come in,'),
  ('0a6e4a95-b34b-5531-ab39-ac63a9c6acde', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 26, 26, 'and so all Israel will be saved. Even as it is written, "There will come out of Zion the Deliverer, and he will turn away ungodliness from Jacob.'),
  ('656aabd9-71b7-5084-a3cf-dc94bd1e1183', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 27, 27, 'This is my covenant to them, when I will take away their sins."'),
  ('a0624b1b-3946-5cc3-acb4-b6323c8f8241', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 28, 28, 'Concerning the Good News, they are enemies for your sake. But concerning the election, they are beloved for the fathers'' sake.'),
  ('bb171e0d-4f58-569f-a30f-cb8c871f1441', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 29, 29, 'For the gifts and the calling of God are irrevocable.'),
  ('3ff968d2-4c8a-5c8f-a3af-ceb04d118747', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 30, 30, 'For as you in time past were disobedient to God, but now have obtained mercy by their disobedience,'),
  ('029ed562-03e7-5166-ac63-1e69ef6c9199', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 31, 31, 'even so these also have now been disobedient, that by the mercy shown to you they may also obtain mercy.'),
  ('c12d14f9-76eb-528d-a855-878826e8728e', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 32, 32, 'For God has shut up all to disobedience, that he might have mercy on all.'),
  ('f11d881e-b47e-5a4d-a826-b3a6a5c5ccd6', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 33, 33, 'Oh the depth of the riches both of the wisdom and the knowledge of God! How unsearchable are his judgments, and his ways past tracing out!'),
  ('ba9a8a1a-61f8-54fb-a307-2e8ab6e1a839', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 34, 34, '"For who has known the mind of the Lord? Or who has been his counselor?"'),
  ('feb9070f-9576-55bb-aed3-c0a1fe66a7a7', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 35, 35, '"Or who has first given to him, and it will be repaid to him again?"'),
  ('6a3dc721-4b5e-5460-ad37-df8da54d3b45', '0661456f-4f14-5679-a657-550cb1e14069', NULL, 36, 36, 'For of him, and through him, and to him, are all things. To him be the glory for ever! Amen.'),
  ('b02ef548-662b-5b5f-afd3-b8495030bdc8', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 1, 1, 'Therefore I urge you, brothers, by the mercies of God, to present your bodies a living sacrifice, holy, acceptable to God, which is your spiritual service.'),
  ('d06fa963-1f44-5437-a868-e5d9aa10ad63', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 2, 2, 'Don''t be conformed to this world, but be transformed by the renewing of your mind, so that you may prove what is the good, well-pleasing, and perfect will of God.'),
  ('2cb8f318-54e8-5263-ac4f-7910e07b15a4', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 3, 3, 'For I say, through the grace that was given me, to every man who is among you, not to think of himself more highly than he ought to think; but to think reasonably, as God has apportioned to each person a measure of faith.'),
  ('61f39075-472e-5a94-aafc-908e5e74d2d0', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 4, 4, 'For even as we have many members in one body, and all the members don''t have the same function,'),
  ('8b04b5c5-79f4-5606-a003-d059592c3a80', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 5, 5, 'so we, who are many, are one body in Christ, and individually members one of another.'),
  ('e97ad64b-7856-51d3-a4ba-f92a51ed22b2', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 6, 6, 'Having gifts differing according to the grace that was given to us, if prophecy, let us prophesy according to the proportion of our faith;'),
  ('7dd161de-848f-5e3e-ac10-1b6b9377890d', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 7, 7, 'or service, let us give ourselves to service; or he who teaches, to his teaching;'),
  ('830d79c0-de08-525a-aac3-ba964e057bf8', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 8, 8, 'or he who exhorts, to his exhorting: he who gives, let him do it with liberality; he who rules, with diligence; he who shows mercy, with cheerfulness.'),
  ('482b7aaa-c898-5940-ae41-8bf92cc9bd01', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 9, 9, 'Let love be without hypocrisy. Abhor that which is evil. Cling to that which is good.'),
  ('963e59b2-03c6-5f0a-a10f-5eab5e51181b', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 10, 10, 'In love of the brothers be tenderly affectionate one to another; in honor preferring one another;'),
  ('d9aa2401-575e-5c71-ad08-f0feb1afa318', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 11, 11, 'not lagging in diligence; fervent in spirit; serving the Lord;'),
  ('9c2fe86c-0c19-5edd-a920-c863beb01d55', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 12, 12, 'rejoicing in hope; enduring in troubles; continuing steadfastly in prayer;'),
  ('f90b86b2-e338-501a-a991-789d4ded9769', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 13, 13, 'contributing to the needs of the saints; given to hospitality.'),
  ('a7a04e27-4ea9-54dc-a3a7-2e1e3146b5a1', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 14, 14, 'Bless those who persecute you; bless, and don''t curse.'),
  ('95a04747-0b8f-51d6-acfc-613c2e1160f6', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 15, 15, 'Rejoice with those who rejoice. Weep with those who weep.'),
  ('6bfc5c1b-c682-56ed-a31b-3cfed93d1286', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 16, 16, 'Be of the same mind one toward another. Don''t set your mind on high things, but associate with the humble. Don''t be wise in your own conceits.'),
  ('8ff6fd7c-4656-512e-a3ab-d202a2b42948', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 17, 17, 'Repay no one evil for evil. Respect what is honorable in the sight of all men.'),
  ('e2e75314-fc52-5268-a279-799221717c1a', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 18, 18, 'If it is possible, as much as it is up to you, be at peace with all men.'),
  ('0bcee969-44d3-52bd-a6a4-5a462ae04202', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 19, 19, 'Don''t seek revenge yourselves, beloved, but give place to God''s wrath. For it is written, "Vengeance belongs to me; I will repay, says the Lord."'),
  ('43e0026a-83a8-503d-ad0d-708f48be712a', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 20, 20, 'Therefore "If your enemy is hungry, feed him. If he is thirsty, give him a drink; for in doing so, you will heap coals of fire on his head."'),
  ('ee3b387e-6a4f-5424-a1c9-969876c93403', '8e410ede-3d91-548b-a4e8-045770c95979', NULL, 21, 21, 'Don''t be overcome by evil, but overcome evil with good.'),
  ('031d7532-b5c6-5157-a3b6-eeb69eebe151', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 1, 1, 'Let every soul be in subjection to the higher authorities, for there is no authority except from God, and those who exist are ordained by God.'),
  ('9407eba4-5333-5d77-a352-206e08d7e8cb', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 2, 2, 'Therefore he who resists the authority, withstands the ordinance of God; and those who withstand will receive to themselves judgment.'),
  ('819feb56-2581-519f-a9da-aaa1959ef027', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 3, 3, 'For rulers are not a terror to the good work, but to the evil. Do you desire to have no fear of the authority? Do that which is good, and you will have praise from the same,'),
  ('2c09fe02-acb8-50a6-a456-a796c32be203', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 4, 4, 'for he is a servant of God to you for good. But if you do that which is evil, be afraid, for he doesn''t bear the sword in vain; for he is a servant of God, an avenger for wrath to him who does evil.'),
  ('24f71731-2008-5f5c-a97d-725dd68ab5c9', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 5, 5, 'Therefore you need to be in subjection, not only because of the wrath, but also for conscience'' sake.'),
  ('befe7c42-e9c6-5b2f-adcf-b449f293f55f', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 6, 6, 'For this reason you also pay taxes, for they are servants of God''s service, attending continually on this very thing.'),
  ('0b9df8a9-a990-5bb1-a853-406fdbfa9834', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 7, 7, 'Give therefore to everyone what you owe: taxes to whom taxes are due; customs to whom customs; respect to whom respect; honor to whom honor.'),
  ('a6c5a73c-cae3-5c6f-a855-872f0a56ac6d', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 8, 8, 'Owe no one anything, except to love one another; for he who loves his neighbor has fulfilled the law.'),
  ('585c3092-a5bf-5302-ad4a-00c703d60778', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 9, 9, 'For the commandments, "You shall not commit adultery," "You shall not murder," "You shall not steal," "You shall not give false testimony," "You shall not covet," and whatever other commandments there are, are all summed up in this saying, namely, "You shall love your neighbor as yourself."'),
  ('80a1dce3-4802-536a-acef-8a64ba2d7993', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 10, 10, 'Love doesn''t harm a neighbor. Love therefore is the fulfillment of the law.'),
  ('cede6c85-5374-5dd8-a4ca-d04bd2925c36', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 11, 11, 'Do this, knowing the time, that it is already time for you to awaken out of sleep, for salvation is now nearer to us than when we first believed.'),
  ('7fe0beac-70ba-5b9f-ac4d-a8aeceddf6f1', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 12, 12, 'The night is far gone, and the day is near. Let''s therefore throw off the works of darkness, and let''s put on the armor of light.'),
  ('5a3b777f-274c-5c46-ab78-428c86de6609', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 13, 13, 'Let us walk properly, as in the day; not in reveling and drunkenness, not in sexual promiscuity and lustful acts, and not in strife and jealousy.'),
  ('8b9838bb-8320-53f9-a822-b3380a492d49', 'dc97247a-bbaa-54b4-abf0-a03ec317be38', NULL, 14, 14, 'But put on the Lord Jesus Christ, and make no provision for the flesh, for its lusts.'),
  ('054794d7-16e1-5441-a41b-396b26f07d67', '13667b81-6932-5576-a380-53401ed1feea', NULL, 1, 1, 'Now accept one who is weak in faith, but not for disputes over opinions.'),
  ('3bd474f2-d3ff-547a-a001-6c0c0ce88f3c', '13667b81-6932-5576-a380-53401ed1feea', NULL, 2, 2, 'One man has faith to eat all things, but he who is weak eats only vegetables.'),
  ('a2ce6dbd-9214-579a-afa0-c71c31fefa55', '13667b81-6932-5576-a380-53401ed1feea', NULL, 3, 3, 'Don''t let him who eats despise him who doesn''t eat. Don''t let him who doesn''t eat judge him who eats, for God has accepted him.'),
  ('9f3c8285-c74f-54d3-a17d-fc3729e5bca6', '13667b81-6932-5576-a380-53401ed1feea', NULL, 4, 4, 'Who are you who judge another''s servant? To his own lord he stands or falls. Yes, he will be made to stand, for God has power to make him stand.'),
  ('cc7eed8d-0d12-54fd-a1de-d3984a09a208', '13667b81-6932-5576-a380-53401ed1feea', NULL, 5, 5, 'One man esteems one day as more important. Another esteems every day alike. Let each man be fully assured in his own mind.'),
  ('4c1c7557-d29c-51d7-aebb-168439b730ad', '13667b81-6932-5576-a380-53401ed1feea', NULL, 6, 6, 'He who observes the day, observes it to the Lord; and he who does not observe the day, to the Lord he does not observe it. He who eats, eats to the Lord, for he gives God thanks. He who doesn''t eat, to the Lord he doesn''t eat, and gives God thanks.'),
  ('9047e2dd-9542-5fe5-ae61-6936cceaefec', '13667b81-6932-5576-a380-53401ed1feea', NULL, 7, 7, 'For none of us lives to himself, and none dies to himself.'),
  ('5e7d804e-c387-5088-ad0a-80ad6112009c', '13667b81-6932-5576-a380-53401ed1feea', NULL, 8, 8, 'For if we live, we live to the Lord. Or if we die, we die to the Lord. If therefore we live or die, we are the Lord''s.'),
  ('411276d8-778b-51b4-adab-064974fb41d8', '13667b81-6932-5576-a380-53401ed1feea', NULL, 9, 9, 'For to this end Christ died, rose, and lived again, that he might be Lord of both the dead and the living.'),
  ('3f92ab24-ac88-5d5c-adb9-839f903bd9a9', '13667b81-6932-5576-a380-53401ed1feea', NULL, 10, 10, 'But you, why do you judge your brother? Or you again, why do you despise your brother? For we will all stand before the judgment seat of Christ.'),
  ('e65a569c-2a96-5fea-a8e4-479651aa8291', '13667b81-6932-5576-a380-53401ed1feea', NULL, 11, 11, 'For it is written, "''As I live,'' says the Lord, ''to me every knee will bow. Every tongue will confess to God.''"'),
  ('46d9e250-5bb1-54ad-a188-0e8a9d4ce5a1', '13667b81-6932-5576-a380-53401ed1feea', NULL, 12, 12, 'So then each one of us will give account of himself to God.'),
  ('94f97b21-d5ba-55e7-a470-2f75d13b13ef', '13667b81-6932-5576-a380-53401ed1feea', NULL, 13, 13, 'Therefore let''s not judge one another any more, but judge this rather, that no man put a stumbling block in his brother''s way, or an occasion for falling.'),
  ('d52bfccf-2372-5b7f-a31f-891ba46e3ece', '13667b81-6932-5576-a380-53401ed1feea', NULL, 14, 14, 'I know, and am persuaded in the Lord Jesus, that nothing is unclean of itself; except that to him who considers anything to be unclean, to him it is unclean.'),
  ('15d6cbb0-be56-5073-aa0f-82ee82f7c707', '13667b81-6932-5576-a380-53401ed1feea', NULL, 15, 15, 'Yet if because of food your brother is grieved, you walk no longer in love. Don''t destroy with your food him for whom Christ died.'),
  ('ac0e05cd-cfca-5213-ad70-5938c6f606d9', '13667b81-6932-5576-a380-53401ed1feea', NULL, 16, 16, 'Then don''t let your good be slandered,'),
  ('3ce673a7-a382-5ba8-a999-543922ab9704', '13667b81-6932-5576-a380-53401ed1feea', NULL, 17, 17, 'for the Kingdom of God is not eating and drinking, but righteousness, peace, and joy in the Holy Spirit.'),
  ('57c42265-6b8b-5dbb-a322-88e5d3dac349', '13667b81-6932-5576-a380-53401ed1feea', NULL, 18, 18, 'For he who serves Christ in these things is acceptable to God and approved by men.'),
  ('b0583bdc-4908-5126-ace2-f8425bd15a8a', '13667b81-6932-5576-a380-53401ed1feea', NULL, 19, 19, 'So then, let us follow after things which make for peace, and things by which we may build one another up.'),
  ('fcdb41ad-c33e-5109-a493-fad27ac1434d', '13667b81-6932-5576-a380-53401ed1feea', NULL, 20, 20, 'Don''t overthrow God''s work for food''s sake. All things indeed are clean, however it is evil for that man who creates a stumbling block by eating.'),
  ('62781bfc-e3fd-558e-a02a-4c50fdedf100', '13667b81-6932-5576-a380-53401ed1feea', NULL, 21, 21, 'It is good to not eat meat, drink wine, nor do anything by which your brother stumbles, is offended, or is made weak.'),
  ('cae4ac53-7c8b-5bed-aa07-24fbfc7d7c14', '13667b81-6932-5576-a380-53401ed1feea', NULL, 22, 22, 'Do you have faith? Have it to yourself before God. Happy is he who doesn''t judge himself in that which he approves.'),
  ('29c7746d-e888-5331-ab64-67a163c3ab8e', '13667b81-6932-5576-a380-53401ed1feea', NULL, 23, 23, 'But he who doubts is condemned if he eats, because it isn''t of faith; and whatever is not of faith is sin.'),
  ('bfca27af-c400-5f36-a0b2-3d1798e79cd4', '13667b81-6932-5576-a380-53401ed1feea', NULL, 24, 24, 'Now to him who is able to establish you according to my Good News and the preaching of Jesus Christ, according to the revelation of the mystery which has been kept secret through long ages,'),
  ('e5c45e1e-7d8b-5ad2-a8e3-38c0b3b9f5ac', '13667b81-6932-5576-a380-53401ed1feea', NULL, 25, 25, 'but now is revealed, and by the Scriptures of the prophets, according to the commandment of the eternal God, is made known for obedience of faith to all the nations;'),
  ('197dfd2c-16ac-528e-a4b8-c58098969884', '13667b81-6932-5576-a380-53401ed1feea', NULL, 26, 26, 'to the only wise God, through Jesus Christ, to whom be the glory forever! Amen.'),
  ('c7da1f7f-91a2-5385-a374-f99578ab80de', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 1, 1, 'Now we who are strong ought to bear the weaknesses of the weak, and not to please ourselves.'),
  ('cfe7730e-30c5-5da7-ab7a-b659f6919d22', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 2, 2, 'Let each one of us please his neighbor for that which is good, to be building him up.'),
  ('4f62de3f-69d0-55eb-a7e8-8ad04a5ebfa9', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 3, 3, 'For even Christ didn''t please himself. But, as it is written, "The reproaches of those who reproached you fell on me."'),
  ('a65b8bc1-a5ea-5463-a7e1-eac8c0fd6848', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 4, 4, 'For whatever things were written before were written for our learning, that through patience and through encouragement of the Scriptures we might have hope.'),
  ('8faeca0d-405b-517e-a42b-c25ef2d8a0e2', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 5, 5, 'Now the God of patience and of encouragement grant you to be of the same mind one with another according to Christ Jesus,'),
  ('fc340e0b-fabb-5e54-af24-7f9485a7ff40', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 6, 6, 'that with one accord you may with one mouth glorify the God and Father of our Lord Jesus Christ.'),
  ('87419776-d6fd-582c-a1df-5bb48cff394b', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 7, 7, 'Therefore accept one another, even as Christ also accepted you, to the glory of God.'),
  ('b0fa643a-841c-5352-a255-3cd3571745a3', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 8, 8, 'Now I say that Christ has been made a servant of the circumcision for the truth of God, that he might confirm the promises given to the fathers,'),
  ('5b893fc3-129c-59e5-acc7-405cac3e742a', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 9, 9, 'and that the Gentiles might glorify God for his mercy. As it is written, "Therefore will I give praise to you among the Gentiles, and sing to your name."'),
  ('ad9f7eda-31f4-5ee5-a6e9-780f342e02a3', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 10, 10, 'Again he says, "Rejoice, you Gentiles, with his people."'),
  ('1ea8541a-2dfb-5bf4-a2ef-5e8b1a5985c9', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 11, 11, 'Again, "Praise the Lord, all you Gentiles! Let all the peoples praise him."'),
  ('0456663a-5cf6-528c-a50f-43852649d3ed', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 12, 12, 'Again, Isaiah says, "There will be the root of Jesse, he who arises to rule over the Gentiles; in him the Gentiles will hope."'),
  ('bfdeed0b-6f05-5760-af92-0a5e8afdba0f', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 13, 13, 'Now may the God of hope fill you with all joy and peace in believing, that you may abound in hope, in the power of the Holy Spirit.'),
  ('661de0fe-fb69-56a0-a38b-b6c79dd3ada8', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 14, 14, 'I myself am also persuaded about you, my brothers, that you yourselves are full of goodness, filled with all knowledge, able also to admonish others.'),
  ('2eca44c5-9f4e-56f6-a62f-819840ebd2a0', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 15, 15, 'But I write the more boldly to you in part, as reminding you, because of the grace that was given to me by God,'),
  ('b250d16c-b4a1-5a00-aa81-d9da0fd6b0df', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 16, 16, 'that I should be a servant of Christ Jesus to the Gentiles, serving as a priest the Good News of God, that the offering up of the Gentiles might be made acceptable, sanctified by the Holy Spirit.'),
  ('45f6bae6-7716-51f5-af11-9b2e00171bb2', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 17, 17, 'I have therefore my boasting in Christ Jesus in things pertaining to God.'),
  ('91bf4990-d80b-5339-ac38-159b07fc9032', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 18, 18, 'For I will not dare to speak of any things except those which Christ worked through me, for the obedience of the Gentiles, by word and deed,'),
  ('240940d4-49fa-595c-a347-ee3b497bc9ca', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 19, 19, 'in the power of signs and wonders, in the power of God''s Spirit; so that from Jerusalem, and around as far as to Illyricum, I have fully preached the Good News of Christ;'),
  ('fbe77775-ff3b-52dc-a5ae-c92e247c3e77', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 20, 20, 'yes, making it my aim to preach the Good News, not where Christ was already named, that I might not build on another''s foundation.'),
  ('0c204a4f-f008-5998-ae0c-5d4399e5e7e3', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 21, 21, 'But, as it is written, "They will see, to whom no news of him came. They who haven''t heard will understand."'),
  ('70ac01d6-9444-512b-a012-9aa077dff459', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 22, 22, 'Therefore also I was hindered these many times from coming to you,'),
  ('9fbcc925-006a-5511-a82c-95dc9dcc685e', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 23, 23, 'but now, no longer having any place in these regions, and having these many years a longing to come to you,'),
  ('c2810209-fff9-58ca-ae81-6433e3a676d4', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 24, 24, 'whenever I journey to Spain, I will come to you. For I hope to see you on my journey, and to be helped on my way there by you, if first I may enjoy your company for a while.'),
  ('33ad63d0-7b18-5cba-ae39-13841bd9f213', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 25, 25, 'But now, I say, I am going to Jerusalem, serving the saints.'),
  ('3995fc19-686d-5da9-a58e-a4026d88ae4d', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 26, 26, 'For it has been the good pleasure of Macedonia and Achaia to make a certain contribution for the poor among the saints who are at Jerusalem.'),
  ('229a4afb-c0e5-5a89-a458-2a7ebaea1dc3', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 27, 27, 'Yes, it has been their good pleasure, and they are their debtors. For if the Gentiles have been made partakers of their spiritual things, they owe it to them also to serve them in fleshly things.'),
  ('a8c6c74a-30c2-5050-a48b-122968bfaf5c', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 28, 28, 'When therefore I have accomplished this, and have sealed to them this fruit, I will go on by way of you to Spain.'),
  ('18baafd5-73f2-586e-a85f-f2029bcf7e50', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 29, 29, 'I know that, when I come to you, I will come in the fullness of the blessing of the Good News of Christ.'),
  ('d90c9277-6005-5f54-a495-445a4017e392', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 30, 30, 'Now I beg you, brothers, by our Lord Jesus Christ, and by the love of the Spirit, that you strive together with me in your prayers to God for me,'),
  ('5ac5b56e-b06a-56c7-accd-034a2ba225e7', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 31, 31, 'that I may be delivered from those who are disobedient in Judea, and that my service which I have for Jerusalem may be acceptable to the saints;'),
  ('f0bf410f-b1c1-593c-afac-e88ea5f897f4', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 32, 32, 'that I may come to you in joy through the will of God, and together with you, find rest.'),
  ('083e6043-a482-5261-a2cf-ff13599ad7af', '21e2634f-afb1-5271-af50-0c78294e7c00', NULL, 33, 33, 'Now the God of peace be with you all. Amen.'),
  ('710ca5be-abc9-5d39-a73d-e715a0775821', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 1, 1, 'I commend to you Phoebe, our sister, who is a servant of the assembly that is at Cenchreae,'),
  ('aeba4d2e-0fd4-5df0-a911-fcd1de482080', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 2, 2, 'that you receive her in the Lord, in a way worthy of the saints, and that you assist her in whatever matter she may need from you, for she herself also has been a helper of many, and of my own self.'),
  ('df6f98f6-8e3f-5eac-ad8b-c8573f858502', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 3, 3, 'Greet Prisca and Aquila, my fellow workers in Christ Jesus,'),
  ('40d93d5e-a003-50d3-a57a-fb814d9c5f98', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 4, 4, 'who for my life, laid down their own necks; to whom not only I give thanks, but also all the assemblies of the Gentiles.'),
  ('63b87138-7b85-5b8b-a718-642dc15df429', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 5, 5, 'Greet the assembly that is in their house. Greet Epaenetus, my beloved, who is the first fruits of Achaia to Christ.'),
  ('5d241ab7-a463-5c23-a8c4-d3f84b772342', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 6, 6, 'Greet Mary, who labored much for us.'),
  ('b0126a3b-a0ee-5b17-a50b-0cfa6c0ae85a', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 7, 7, 'Greet Andronicus and Junia, my relatives and my fellow prisoners, who are notable among the apostles, who also were in Christ before me.'),
  ('0d8ef9ee-55d9-590d-aad0-8e7f7f21099d', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 8, 8, 'Greet Amplias, my beloved in the Lord.'),
  ('31328bc5-57c3-521d-aa98-2ffb1895ad7f', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 9, 9, 'Greet Urbanus, our fellow worker in Christ, and Stachys, my beloved.'),
  ('f6ffc28d-7e75-5067-abb1-a68a1dca046e', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 10, 10, 'Greet Apelles, the approved in Christ. Greet those who are of the household of Aristobulus.'),
  ('91df0707-3bee-5cbd-a341-b6adb68de982', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 11, 11, 'Greet Herodion, my kinsman. Greet them of the household of Narcissus, who are in the Lord.'),
  ('9e643be7-be65-50ed-a077-8effff649a90', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 12, 12, 'Greet Tryphaena and Tryphosa, who labor in the Lord. Greet Persis, the beloved, who labored much in the Lord.'),
  ('ad1696d3-acb0-5dd9-a664-02c1c9b2e95b', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 13, 13, 'Greet Rufus, the chosen in the Lord, and his mother and mine.'),
  ('3924807e-65f4-5290-af80-d612eaa29ebb', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 14, 14, 'Greet Asyncritus, Phlegon, Hermes, Patrobas, Hermas, and the brothers who are with them.'),
  ('7de4df3a-9897-5946-a024-94b5a76ed982', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 15, 15, 'Greet Philologus and Julia, Nereus and his sister, and Olympas, and all the saints who are with them.'),
  ('1c488008-6132-564a-a0c8-033fb8adbc67', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 16, 16, 'Greet one another with a holy kiss. The assemblies of Christ greet you.'),
  ('1a91e2a4-f843-5131-ad88-09a65ab0fd3c', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 17, 17, 'Now I beg you, brothers, look out for those who are causing the divisions and occasions of stumbling, contrary to the doctrine which you learned, and turn away from them.'),
  ('3d2ff91d-103a-5dda-a765-c4b75f890136', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 18, 18, 'For those who are such don''t serve our Lord, Jesus Christ, but their own belly; and by their smooth and flattering speech, they deceive the hearts of the innocent.'),
  ('10b33ef4-276e-54bd-ad72-2fe0ad138330', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 19, 19, 'For your obedience has become known to all. I rejoice therefore over you. But I desire to have you wise in that which is good, but innocent in that which is evil.'),
  ('c7c1f64e-6a16-5d55-ac77-185cb0a6ddf9', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 20, 20, 'And the God of peace will quickly crush Satan under your feet. The grace of our Lord Jesus Christ be with you.'),
  ('2114dfbf-e0b6-5cd5-a689-c2660d913770', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 21, 21, 'Timothy, my fellow worker, greets you, as do Lucius, Jason, and Sosipater, my relatives.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('dc8ac116-22d0-5b67-a45e-24ebc5d046c5', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 22, 22, 'I, Tertius, who write the letter, greet you in the Lord.'),
  ('b9c398bd-fbb7-5e1f-ad12-748ae749571c', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 23, 23, 'Gaius, my host and host of the whole assembly, greets you. Erastus, the treasurer of the city, greets you, as does Quartus, the brother.'),
  ('a537f04e-93f1-5ee4-a21a-a92d29ee2ba0', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 24, 24, 'The grace of our Lord Jesus Christ be with you all! Amen.'),
  ('8adabd6e-30b1-53b1-a350-024215424b57', 'e2d4abb5-4f6f-52ab-a703-690a289b54c4', NULL, 25, 25, ''),
  ('b389d13d-e289-5fe2-a1b4-1ef9d5e16082', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 1, 1, 'Paul, called to be an apostle of Jesus Christ through the will of God, and our brother Sosthenes,'),
  ('dd26bb51-cd25-5b46-a7f4-962086b3e25c', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 2, 2, 'to the assembly of God which is at Corinth; those who are sanctified in Christ Jesus, called to be saints, with all who call on the name of our Lord Jesus Christ in every place, both theirs and ours:'),
  ('d53630d4-3520-5ac7-a55a-cd5e9c5c8129', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 3, 3, 'Grace to you and peace from God our Father and the Lord Jesus Christ.'),
  ('1fbde6f7-4364-55ea-aa63-251be985275b', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 4, 4, 'I always thank my God concerning you, for the grace of God which was given you in Christ Jesus;'),
  ('6aff1d13-f4ce-537e-a978-9d147f25fb36', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 5, 5, 'that in everything you were enriched in him, in all speech and all knowledge;'),
  ('581707fc-62c7-5e95-aed9-3f22dd6119b8', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 6, 6, 'even as the testimony of Christ was confirmed in you:'),
  ('5fc92e1c-fa9c-5104-ae49-e6d8cfa647a7', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 7, 7, 'so that you come behind in no gift; waiting for the revelation of our Lord Jesus Christ;'),
  ('e7d60fb2-2611-50e3-af49-4b80594bad69', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 8, 8, 'who will also confirm you until the end, blameless in the day of our Lord Jesus Christ.'),
  ('5217efa7-2351-5d02-aeb6-9c14009265c5', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 9, 9, 'God is faithful, through whom you were called into the fellowship of his Son, Jesus Christ, our Lord.'),
  ('e9a3c0d9-89aa-574d-ae52-c6271dd58bc8', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 10, 10, 'Now I beg you, brothers, through the name of our Lord, Jesus Christ, that you all speak the same thing and that there be no divisions among you, but that you be perfected together in the same mind and in the same judgment.'),
  ('c62b3a60-2f36-592f-a6c3-60fa2de50a76', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 11, 11, 'For it has been reported to me concerning you, my brothers, by those who are from Chloe''s household, that there are contentions among you.'),
  ('aa3988e0-842f-56ab-aeb1-8c63524b10e8', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 12, 12, 'Now I mean this, that each one of you says, "I follow Paul," "I follow Apollos," "I follow Cephas," and, "I follow Christ."'),
  ('b2a990c6-dab9-5fcb-aa4f-7d7a9698e815', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 13, 13, 'Is Christ divided? Was Paul crucified for you? Or were you baptized into the name of Paul?'),
  ('1cb796b7-6f97-526f-afab-d7928d068b37', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 14, 14, 'I thank God that I baptized none of you, except Crispus and Gaius,'),
  ('0c45ea3b-0cdf-5736-a09d-c0aedae225dc', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 15, 15, 'so that no one should say that I had baptized you into my own name.'),
  ('0c4b9f37-145e-5e45-a4cf-74172ee3b874', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 16, 16, '(I also baptized the household of Stephanas; besides them, I don''t know whether I baptized any other.)'),
  ('004bcbf1-29e8-5cd8-a64c-2e9f52f62eb2', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 17, 17, 'For Christ sent me not to baptize, but to preach the Good News--not in wisdom of words, so that the cross of Christ wouldn''t be made void.'),
  ('de6a32eb-34d7-5cdb-aafc-cbb57aa2d8de', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 18, 18, 'For the word of the cross is foolishness to those who are dying, but to us who are saved it is the power of God.'),
  ('966f6fb6-c922-5432-a246-4b70bc09297e', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 19, 19, 'For it is written, "I will destroy the wisdom of the wise, I will bring the discernment of the discerning to nothing."'),
  ('56781590-1bc9-59ec-a52e-b1a038dd55ad', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 20, 20, 'Where is the wise? Where is the scribe? Where is the lawyer of this world? Hasn''t God made foolish the wisdom of this world?'),
  ('334eeeff-58e4-5e74-a3d3-f4c496f73af9', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 21, 21, 'For seeing that in the wisdom of God, the world through its wisdom didn''t know God, it was God''s good pleasure through the foolishness of the preaching to save those who believe.'),
  ('4a3e1a6d-7a87-5fc4-a1fd-2a62dbb32695', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 22, 22, 'For Jews ask for signs, Greeks seek after wisdom,'),
  ('e2617e1f-ffd2-5a87-a869-b280b9e1286f', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 23, 23, 'but we preach Christ crucified; a stumbling block to Jews, and foolishness to Greeks,'),
  ('ed000d04-a506-5223-ab53-0e5a238e58c4', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 24, 24, 'but to those who are called, both Jews and Greeks, Christ is the power of God and the wisdom of God.'),
  ('4f177078-4e66-5044-ac39-fe91f615ed8e', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 25, 25, 'Because the foolishness of God is wiser than men, and the weakness of God is stronger than men.'),
  ('a895d981-63ec-5c7e-a009-fb84a32e3016', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 26, 26, 'For you see your calling, brothers, that not many are wise according to the flesh, not many mighty, and not many noble;'),
  ('638df56e-6227-55b7-a0bb-145fe4f2323e', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 27, 27, 'but God chose the foolish things of the world that he might put to shame those who are wise. God chose the weak things of the world, that he might put to shame the things that are strong;'),
  ('de6703ba-27d3-5d20-a0f0-127172d403ed', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 28, 28, 'and God chose the lowly things of the world, and the things that are despised, and the things that are not, that he might bring to nothing the things that are:'),
  ('982d69e9-28e1-5302-aadf-f8337b7cb0d8', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 29, 29, 'that no flesh should boast before God.'),
  ('a95f9304-d8f4-5616-a55b-8f692bef48a3', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 30, 30, 'But of him, you are in Christ Jesus, who was made to us wisdom from God, and righteousness and sanctification, and redemption:'),
  ('09ddf3fb-80be-5c34-acd8-1baf851cf16d', '06fe608e-02ca-59f8-a8f2-4164620aa765', NULL, 31, 31, 'that, according as it is written, "He who boasts, let him boast in the Lord."'),
  ('2c291741-8101-53bd-a593-d3ca068a1b3d', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 1, 1, 'When I came to you, brothers, I didn''t come with excellence of speech or of wisdom, proclaiming to you the testimony of God.'),
  ('e6942c40-bbb0-5ad7-adc9-b91fc3382baa', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 2, 2, 'For I determined not to know anything among you, except Jesus Christ, and him crucified.'),
  ('85f7677f-2174-5df4-a168-e3ed06da40c7', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 3, 3, 'I was with you in weakness, in fear, and in much trembling.'),
  ('31b5a0b7-1c33-5504-af60-c1d4ed59fd5a', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 4, 4, 'My speech and my preaching were not in persuasive words of human wisdom, but in demonstration of the Spirit and of power,'),
  ('2eb093aa-cef4-5a92-a4fb-03545952d770', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 5, 5, 'that your faith wouldn''t stand in the wisdom of men, but in the power of God.'),
  ('a3ac8ad0-0a02-572f-abd2-3060c582ff17', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 6, 6, 'We speak wisdom, however, among those who are full grown; yet a wisdom not of this world, nor of the rulers of this world, who are coming to nothing.'),
  ('fd48cec1-0bed-5cb1-a87e-d0b6b388fc34', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 7, 7, 'But we speak God''s wisdom in a mystery, the wisdom that has been hidden, which God foreordained before the worlds for our glory,'),
  ('b68f8e41-52c8-523d-a763-320e23720cce', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 8, 8, 'which none of the rulers of this world has known. For had they known it, they wouldn''t have crucified the Lord of glory.'),
  ('91c9f05a-e60e-5dfc-a935-a89a1bb07e85', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 9, 9, 'But as it is written, "Things which an eye didn''t see, and an ear didn''t hear, which didn''t enter into the heart of man, these God has prepared for those who love him."'),
  ('29bdea8a-b9b0-50c6-ac2c-f326b5d0125a', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 10, 10, 'But to us, God revealed them through the Spirit. For the Spirit searches all things, yes, the deep things of God.'),
  ('fa22df29-6193-5ac7-a880-91f691561d0a', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 11, 11, 'For who among men knows the things of a man, except the spirit of the man, which is in him? Even so, no one knows the things of God, except God''s Spirit.'),
  ('e934c9b0-cb69-5f33-ab13-5286f4963e6c', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 12, 12, 'But we received, not the spirit of the world, but the Spirit which is from God, that we might know the things that were freely given to us by God.'),
  ('d30a06c3-e517-5f5a-a5a7-396d3e27a62d', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 13, 13, 'Which things also we speak, not in words which man''s wisdom teaches, but which the Holy Spirit teaches, comparing spiritual things with spiritual things.'),
  ('5b8c506b-7d3f-556b-aa5d-911a8bbfa458', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 14, 14, 'Now the natural man doesn''t receive the things of God''s Spirit, for they are foolishness to him, and he can''t know them, because they are spiritually discerned.'),
  ('b8e59ef4-fe1e-5911-a25e-931ae2824406', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 15, 15, 'But he who is spiritual discerns all things, and he himself is judged by no one.'),
  ('bc68dbac-29c1-5d8a-aa7f-be176abcef18', 'c975d527-5f45-5a71-a927-da8130a32edb', NULL, 16, 16, '"For who has known the mind of the Lord, that he should instruct him?" But we have Christ''s mind.'),
  ('ce05abc5-8a43-57e8-a506-e8f36bf28f1e', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 1, 1, 'Brothers, I couldn''t speak to you as to spiritual, but as to fleshly, as to babies in Christ.'),
  ('b1df6223-f770-5a71-a757-f20bb7ddca66', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 2, 2, 'I fed you with milk, not with meat; for you weren''t yet ready. Indeed, not even now are you ready,'),
  ('7f17fb4f-8825-508b-aaa5-b57cb0aba0e9', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 3, 3, 'for you are still fleshly. For insofar as there is jealousy, strife, and factions among you, aren''t you fleshly, and don''t you walk in the ways of men?'),
  ('fd8b1e42-57ea-55f9-afa2-833d07049644', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 4, 4, 'For when one says, "I follow Paul," and another, "I follow Apollos," aren''t you fleshly?'),
  ('687e4fae-39aa-56d9-a3cc-e1ee9cc27eae', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 5, 5, 'Who then is Apollos, and who is Paul, but servants through whom you believed; and each as the Lord gave to him?'),
  ('6b729a2c-4c39-54f4-a4f3-a4cc671f941c', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 6, 6, 'I planted. Apollos watered. But God gave the increase.'),
  ('5d79a623-437d-5ec6-ad09-df3dfc2ccf36', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 7, 7, 'So then neither he who plants is anything, nor he who waters, but God who gives the increase.'),
  ('6d2167fa-83ba-5140-a229-6a8024eadc83', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 8, 8, 'Now he who plants and he who waters are the same, but each will receive his own reward according to his own labor.'),
  ('daee5cab-50a3-5eb0-a261-0fcfeb0e2d22', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 9, 9, 'For we are God''s fellow workers. You are God''s farming, God''s building.'),
  ('255a2aa1-e996-5b2a-a6c8-0a091cf7d5ad', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 10, 10, 'According to the grace of God which was given to me, as a wise master builder I laid a foundation, and another builds on it. But let each man be careful how he builds on it.'),
  ('fc5befb6-7121-5fa1-ab65-12f1b92a62a9', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 11, 11, 'For no one can lay any other foundation than that which has been laid, which is Jesus Christ.'),
  ('3d6815a6-53a5-5c7a-a9c2-36b1f76ead46', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 12, 12, 'But if anyone builds on the foundation with gold, silver, costly stones, wood, hay, or stubble;'),
  ('583a2809-70b9-5e2f-adce-2a36521b48cc', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 13, 13, 'each man''s work will be revealed. For the Day will declare it, because it is revealed in fire; and the fire itself will test what sort of work each man''s work is.'),
  ('b60fcaa9-4b12-5720-a0c6-0fc2caee1449', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 14, 14, 'If any man''s work remains which he built on it, he will receive a reward.'),
  ('8258f3c8-aff0-5c56-a80e-2c73aea14867', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 15, 15, 'If any man''s work is burned, he will suffer loss, but he himself will be saved, but as through fire.'),
  ('1db9a4b7-f70d-5094-a56a-8f352e1ae993', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 16, 16, 'Don''t you know that you are a temple of God, and that God''s Spirit lives in you?'),
  ('84249b67-a3e1-54e5-ab22-c8c6e7e9d71c', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 17, 17, 'If anyone destroys the temple of God, God will destroy him; for God''s temple is holy, which you are.'),
  ('62ccd53e-825f-5c21-a87f-fccb7a8929f6', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 18, 18, 'Let no one deceive himself. If anyone thinks that he is wise among you in this world, let him become a fool, that he may become wise.'),
  ('612f7d54-835d-5ad6-a46c-86bae5f71092', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 19, 19, 'For the wisdom of this world is foolishness with God. For it is written, "He has taken the wise in their craftiness."'),
  ('38a1f7a4-60ba-5a03-a4ed-430c308ace35', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 20, 20, 'And again, "The Lord knows the reasoning of the wise, that it is worthless."'),
  ('15977265-af5e-51a9-a7f0-346ad567a01a', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 21, 21, 'Therefore let no one boast in men. For all things are yours,'),
  ('25de417e-6877-54f1-a694-d71b51fa18d6', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 22, 22, 'whether Paul, or Apollos, or Cephas, or the world, or life, or death, or things present, or things to come. All are yours,'),
  ('4b8b36ed-5229-5c9b-acc9-4964f69f5ae9', '650ab1f4-e6ec-5cf9-a234-ea0527c09efa', NULL, 23, 23, 'and you are Christ''s, and Christ is God''s.'),
  ('ff036a07-a81c-53e0-a679-8c945184f988', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 1, 1, 'So let a man think of us as Christ''s servants, and stewards of God''s mysteries.'),
  ('4457488a-ce18-5acc-a23c-2b4db689d8e4', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 2, 2, 'Here, moreover, it is required of stewards, that they be found faithful.'),
  ('7bf3f284-976f-541b-a9f6-05e9a61737b6', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 3, 3, 'But with me it is a very small thing that I should be judged by you, or by man''s judgment. Yes, I don''t judge my own self.'),
  ('7c79846c-1c07-5ca0-ae99-f1ade5278003', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 4, 4, 'For I know nothing against myself. Yet I am not justified by this, but he who judges me is the Lord.'),
  ('4bae347c-b8a1-5cc6-ab6f-ffdaa10590b0', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 5, 5, 'Therefore judge nothing before the time, until the Lord comes, who will both bring to light the hidden things of darkness, and reveal the counsels of the hearts. Then each man will get his praise from God.'),
  ('e25421d4-f727-5728-a455-c0ca0643656f', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 6, 6, 'Now these things, brothers, I have in a figure transferred to myself and Apollos for your sakes, that in us you might learn not to think beyond the things which are written, that none of you be puffed up against one another.'),
  ('4240b16f-4d20-58c7-a5f7-d9fd0b66fdde', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 7, 7, 'For who makes you different? And what do you have that you didn''t receive? But if you did receive it, why do you boast as if you had not received it?'),
  ('0acb4241-7bf3-5586-a8bc-4a5f570b4cbd', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 8, 8, 'You are already filled. You have already become rich. You have come to reign without us. Yes, and I wish that you did reign, that we also might reign with you.'),
  ('84a05589-35fe-56e7-a209-e409adb96bc4', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 9, 9, 'For, I think that God has displayed us, the apostles, last of all, like men sentenced to death. For we are made a spectacle to the world, both to angels and men.'),
  ('897c87f7-2ec8-5307-ab26-5d329b34835c', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 10, 10, 'We are fools for Christ''s sake, but you are wise in Christ. We are weak, but you are strong. You have honor, but we have dishonor.'),
  ('125d7725-3c4c-5ca4-a2b3-dbef0d3f9a00', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 11, 11, 'Even to this present hour we hunger, thirst, are naked, are beaten, and have no certain dwelling place.'),
  ('936e3167-6eea-5d04-a311-c886fa83f6f6', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 12, 12, 'We toil, working with our own hands. When people curse us, we bless. Being persecuted, we endure.'),
  ('c15ef453-3c67-5cee-a968-ab368bfa718b', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 13, 13, 'Being defamed, we entreat. We are made as the filth of the world, the dirt wiped off by all, even until now.'),
  ('82216a06-1c78-5c08-ae5b-08c9eaf6703a', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 14, 14, 'I don''t write these things to shame you, but to admonish you as my beloved children.'),
  ('33909c94-ae16-5bca-a2c9-dee977a759b5', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 15, 15, 'For though you have ten thousand tutors in Christ, yet not many fathers. For in Christ Jesus, I became your father through the Good News.'),
  ('d8e0aac3-def2-52f5-aeeb-f3524aaa4141', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 16, 16, 'I beg you therefore, be imitators of me.'),
  ('b193fe1a-a157-510d-af68-4ef0bfb3bf15', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 17, 17, 'Because of this I have sent Timothy to you, who is my beloved and faithful child in the Lord, who will remind you of my ways which are in Christ, even as I teach everywhere in every assembly.'),
  ('6cebab0e-610e-5495-ac33-c13932de2e0e', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 18, 18, 'Now some are puffed up, as though I were not coming to you.'),
  ('5a499dbd-851c-540f-a480-4485ac5b82e8', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 19, 19, 'But I will come to you shortly, if the Lord is willing. And I will know, not the word of those who are puffed up, but the power.'),
  ('179fcade-2464-5c39-ac72-92caae990402', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 20, 20, 'For the Kingdom of God is not in word, but in power.'),
  ('25fa2d88-a4a2-5ef7-a7a8-5809663ec52b', 'eab91048-bdf7-5653-a470-0631fb0733aa', NULL, 21, 21, 'What do you want? Shall I come to you with a rod, or in love and a spirit of gentleness?'),
  ('9dbf1105-fa1f-5b1f-a6af-32f7c04161eb', '38a73294-8694-54fb-a147-72e549923f86', NULL, 1, 1, 'It is actually reported that there is sexual immorality among you, and such sexual immorality as is not even named among the Gentiles, that one has his father''s wife.'),
  ('7cfe96d5-22d5-5536-ab57-0fc838ef2ab2', '38a73294-8694-54fb-a147-72e549923f86', NULL, 2, 2, 'You are puffed up, and didn''t rather mourn, that he who had done this deed might be removed from among you.'),
  ('52e9537d-1b87-52b5-a011-4a5e64d573f8', '38a73294-8694-54fb-a147-72e549923f86', NULL, 3, 3, 'For I most certainly, as being absent in body but present in spirit, have already, as though I were present, judged him who has done this thing.'),
  ('a5fc8a0d-2355-5fa1-a5d7-f2a45be8591d', '38a73294-8694-54fb-a147-72e549923f86', NULL, 4, 4, 'In the name of our Lord Jesus Christ, you being gathered together, and my spirit, with the power of our Lord Jesus Christ,'),
  ('8b83a402-89ef-5fa6-aa70-0143fd7cfa60', '38a73294-8694-54fb-a147-72e549923f86', NULL, 5, 5, 'are to deliver such a one to Satan for the destruction of the flesh, that the spirit may be saved in the day of the Lord Jesus.'),
  ('a8d82e74-b9c6-5b6d-a4c7-dd0658bbeb51', '38a73294-8694-54fb-a147-72e549923f86', NULL, 6, 6, 'Your boasting is not good. Don''t you know that a little yeast leavens the whole lump?'),
  ('47e7f653-6384-53b3-afff-5fd5bc8d30ad', '38a73294-8694-54fb-a147-72e549923f86', NULL, 7, 7, 'Purge out the old yeast, that you may be a new lump, even as you are unleavened. For indeed Christ, our Passover, has been sacrificed in our place.'),
  ('4a278f69-3423-5561-ac18-6537fe67f550', '38a73294-8694-54fb-a147-72e549923f86', NULL, 8, 8, 'Therefore let us keep the feast, not with old yeast, neither with the yeast of malice and wickedness, but with the unleavened bread of sincerity and truth.'),
  ('8d0f34f3-3509-51eb-a847-33f4d3f55fac', '38a73294-8694-54fb-a147-72e549923f86', NULL, 9, 9, 'I wrote to you in my letter to have no company with sexual sinners;'),
  ('fb49da0f-0324-5ec5-abac-7d78abcc603b', '38a73294-8694-54fb-a147-72e549923f86', NULL, 10, 10, 'yet not at all meaning with the sexual sinners of this world, or with the covetous and extortioners, or with idolaters; for then you would have to leave the world.'),
  ('7e217727-1c3e-5319-aa75-d0ce18607d03', '38a73294-8694-54fb-a147-72e549923f86', NULL, 11, 11, 'But as it is, I wrote to you not to associate with anyone who is called a brother who is a sexual sinner, or covetous, or an idolater, or a slanderer, or a drunkard, or an extortioner. Don''t even eat with such a person.'),
  ('3bc23849-dc38-5d01-acff-cddf9e8dcd32', '38a73294-8694-54fb-a147-72e549923f86', NULL, 12, 12, 'For what have I to do with also judging those who are outside? Don''t you judge those who are within?'),
  ('6de70f71-b877-5c29-aa4a-0371fef9264f', '38a73294-8694-54fb-a147-72e549923f86', NULL, 13, 13, 'But those who are outside, God judges. "Put away the wicked man from among yourselves."'),
  ('ff960314-d2a2-583f-af70-b97182ced674', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 1, 1, 'Dare any of you, having a matter against his neighbor, go to law before the unrighteous, and not before the saints?'),
  ('7883270e-4af4-5ca7-ab9c-3a9bd6ac0acf', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 2, 2, 'Don''t you know that the saints will judge the world? And if the world is judged by you, are you unworthy to judge the smallest matters?'),
  ('7d7d8c25-d0f8-5994-a19d-3e618cd955b2', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 3, 3, 'Don''t you know that we will judge angels? How much more, things that pertain to this life?'),
  ('2647d56e-2a4d-5f4f-a0d4-03a77f926723', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 4, 4, 'If then, you have to judge things pertaining to this life, do you set them to judge who are of no account in the assembly?'),
  ('978b7512-2627-5789-a343-621ebb5a5660', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 5, 5, 'I say this to move you to shame. Isn''t there even one wise man among you who would be able to decide between his brothers?'),
  ('5538d8a1-aa9f-5dd1-ac47-ce87abe7d1c1', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 6, 6, 'But brother goes to law with brother, and that before unbelievers!'),
  ('a3fbd201-a422-557e-a7a8-e3f1f284faa8', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 7, 7, 'Therefore it is already altogether a defect in you, that you have lawsuits one with another. Why not rather be wronged? Why not rather be defrauded?'),
  ('3bf5a61f-2785-5a02-ab19-ce1587cf3efd', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 8, 8, 'No, but you yourselves do wrong, and defraud, and that against your brothers.'),
  ('1143d74f-ae63-50de-a8bd-72001b699e37', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 9, 9, 'Or don''t you know that the unrighteous will not inherit the Kingdom of God? Don''t be deceived. Neither the sexually immoral, nor idolaters, nor adulterers, nor male prostitutes, nor homosexuals,'),
  ('9e282019-0654-5268-ab86-57d458cc8ea0', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 10, 10, 'nor thieves, nor covetous, nor drunkards, nor slanderers, nor extortioners, will inherit the Kingdom of God.'),
  ('5c5867ea-ec5d-5849-a454-648890ed8a73', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 11, 11, 'Such were some of you, but you were washed. But you were sanctified. But you were justified in the name of the Lord Jesus, and in the Spirit of our God.'),
  ('9e03e342-3c66-554a-a427-fcc7919a038c', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 12, 12, '"All things are lawful for me," but not all things are expedient. "All things are lawful for me," but I will not be brought under the power of anything.'),
  ('061495ff-80df-514f-a028-db71580ba7a9', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 13, 13, '"Foods for the belly, and the belly for foods," but God will bring to nothing both it and them. But the body is not for sexual immorality, but for the Lord; and the Lord for the body.'),
  ('438b4820-5610-559a-a873-b4fc32c28c37', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 14, 14, 'Now God raised up the Lord, and will also raise us up by his power.'),
  ('017c23b2-0eb7-5908-a237-1d30d2196a2b', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 15, 15, 'Don''t you know that your bodies are members of Christ? Shall I then take the members of Christ, and make them members of a prostitute? May it never be!'),
  ('07bf8d70-4fac-5e74-a8de-b148981ffc9f', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 16, 16, 'Or don''t you know that he who is joined to a prostitute is one body? For, "The two," says he, "will become one flesh."'),
  ('51a50a55-d2c1-5856-a7d1-9f30b6058906', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 17, 17, 'But he who is joined to the Lord is one spirit.'),
  ('02b8425d-5b1a-59cd-a58f-74d27770915f', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 18, 18, 'Flee sexual immorality! "Every sin that a man does is outside the body," but he who commits sexual immorality sins against his own body.'),
  ('363c9d83-f16d-5749-a83b-5c97a8a7481b', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 19, 19, 'Or don''t you know that your body is a temple of the Holy Spirit which is in you, which you have from God? You are not your own,'),
  ('7cebd78b-a06d-5a31-abd0-2825e0d97e3e', '18714b90-726b-5717-ab54-21e32dd5b2b5', NULL, 20, 20, 'for you were bought with a price. Therefore glorify God in your body and in your spirit, which are God''s.'),
  ('b76b31c1-ed08-5f15-aff4-c2ca7aebe9f7', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 1, 1, 'Now concerning the things about which you wrote to me: it is good for a man not to touch a woman.'),
  ('a980acf8-fdbd-5752-afbe-a7c804e8623a', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 2, 2, 'But, because of sexual immoralities, let each man have his own wife, and let each woman have her own husband.'),
  ('dfa4c6f1-a87f-5725-ad19-e6d876ee6d75', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 3, 3, 'Let the husband render to his wife the affection owed her, and likewise also the wife to her husband.'),
  ('205826d2-d7c1-5f5b-adce-61c92e3bc359', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 4, 4, 'The wife doesn''t have authority over her own body, but the husband. Likewise also the husband doesn''t have authority over his own body, but the wife.'),
  ('f0873dda-e68f-5fba-a6bb-6b969fd31a04', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 5, 5, 'Don''t deprive one another, unless it is by consent for a season, that you may give yourselves to fasting and prayer, and may be together again, that Satan doesn''t tempt you because of your lack of self-control.'),
  ('4bbd88da-7e8e-513e-a3e3-c427057b669b', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 6, 6, 'But this I say by way of concession, not of commandment.'),
  ('401b0cb4-7844-5935-a00f-c7dac982773e', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 7, 7, 'Yet I wish that all men were like me. However each man has his own gift from God, one of this kind, and another of that kind.'),
  ('fa2782df-b68e-50d5-a030-61d7c31a2cb6', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 8, 8, 'But I say to the unmarried and to widows, it is good for them if they remain even as I am.'),
  ('c3999e28-a90f-5525-a61c-c91d0e9361e7', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 9, 9, 'But if they don''t have self-control, let them marry. For it''s better to marry than to burn.'),
  ('f77bd273-68f9-59a4-abed-72785d1d0c7b', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 10, 10, 'But to the married I command--not I, but the Lord--that the wife not leave her husband'),
  ('2d1beee4-fe79-5fdf-ac12-cffbf99535a0', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 11, 11, '(but if she departs, let her remain unmarried, or else be reconciled to her husband), and that the husband not leave his wife.'),
  ('fdf12f75-c48f-5ced-a2ca-cc6bcfd2064a', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 12, 12, 'But to the rest I--not the Lord--say, if any brother has an unbelieving wife, and she is content to live with him, let him not leave her.'),
  ('9774a343-49f8-5c6a-a581-be115b5e5197', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 13, 13, 'The woman who has an unbelieving husband, and he is content to live with her, let her not leave her husband.'),
  ('790542e4-dbfc-562f-a4c2-bc9b6e8f0304', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 14, 14, 'For the unbelieving husband is sanctified in the wife, and the unbelieving wife is sanctified in the husband. Otherwise your children would be unclean, but now they are holy.'),
  ('def06235-a9c9-5414-aacd-c6a6cdbf2b8c', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 15, 15, 'Yet if the unbeliever departs, let there be separation. The brother or the sister is not under bondage in such cases, but God has called us in peace.'),
  ('03560a6a-97d5-5d84-ab9b-fd13ae150ccd', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 16, 16, 'For how do you know, wife, whether you will save your husband? Or how do you know, husband, whether you will save your wife?'),
  ('18d1b1b2-2136-52c2-af5c-a20d6c010249', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 17, 17, 'Only, as the Lord has distributed to each man, as God has called each, so let him walk. So I command in all the assemblies.'),
  ('ad0007f4-33cf-577c-a972-04aac0fae9a5', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 18, 18, 'Was anyone called having been circumcised? Let him not become uncircumcised. Has anyone been called in uncircumcision? Let him not be circumcised.'),
  ('cb985407-e375-549a-ae95-c34bd32dbf04', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 19, 19, 'Circumcision is nothing, and uncircumcision is nothing, but the keeping of the commandments of God.'),
  ('2bd13dcd-31a9-5801-ad9c-d4db907e07fd', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 20, 20, 'Let each man stay in that calling in which he was called.'),
  ('15a3bb48-73c5-5c64-a556-3f50477e6226', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 21, 21, 'Were you called being a bondservant? Don''t let that bother you, but if you get an opportunity to become free, use it.'),
  ('6e57ea2e-e973-56c1-ae80-6c1e546b3f03', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 22, 22, 'For he who was called in the Lord being a bondservant is the Lord''s free man. Likewise he who was called being free is Christ''s bondservant.'),
  ('baacd79f-21ca-5863-a892-c7b692a4e879', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 23, 23, 'You were bought with a price. Don''t become bondservants of men.'),
  ('17414eaa-a065-5789-a97e-0ffd6f73e7b8', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 24, 24, 'Brothers, let each man, in whatever condition he was called, stay in that condition with God.'),
  ('e954d50c-7d1e-5a55-aaf4-077ffcc9d1a2', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 25, 25, 'Now concerning virgins, I have no commandment from the Lord, but I give my judgment as one who has obtained mercy from the Lord to be trustworthy.'),
  ('ac23c6b2-6b8f-50dd-afb3-d34c8f71d513', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 26, 26, 'I think that it is good therefore, because of the distress that is on us, that it is good for a man to be as he is.'),
  ('98fbe947-0841-5489-a9c0-9fad72bac5fc', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 27, 27, 'Are you bound to a wife? Don''t seek to be freed. Are you free from a wife? Don''t seek a wife.'),
  ('fd7666ab-d2dd-5e8a-a168-18985bffe6c5', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 28, 28, 'But if you marry, you have not sinned. If a virgin marries, she has not sinned. Yet such will have oppression in the flesh, and I want to spare you.'),
  ('de9d1bf7-671c-585b-a626-7aed115a9e0b', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 29, 29, 'But I say this, brothers: the time is short, that from now on, both those who have wives may be as though they had none;'),
  ('295726be-e5e1-525b-af70-8909cec7ff44', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 30, 30, 'and those who weep, as though they didn''t weep; and those who rejoice, as though they didn''t rejoice; and those who buy, as though they didn''t possess;'),
  ('19b10a91-f774-5696-a1b6-35e753fb9c38', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 31, 31, 'and those who use the world, as not using it to the fullest. For the mode of this world passes away.'),
  ('15761025-82d5-5f70-a386-a619d8c4d668', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 32, 32, 'But I desire to have you to be free from cares. He who is unmarried is concerned for the things of the Lord, how he may please the Lord;'),
  ('c2fc7288-e4a8-59e5-a487-f4f0f594ac90', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 33, 33, 'but he who is married is concerned about the things of the world, how he may please his wife.'),
  ('9791439f-16e6-59d3-a711-5090ddefce4f', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 34, 34, 'There is also a difference between a wife and a virgin. The unmarried woman cares about the things of the Lord, that she may be holy both in body and in spirit. But she who is married cares about the things of the world--how she may please her husband.'),
  ('ac1dfaeb-cd56-5ea8-a540-59c41cb4b821', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 35, 35, 'This I say for your own profit; not that I may ensnare you, but for that which is appropriate, and that you may attend to the Lord without distraction.'),
  ('82433b14-e0d8-5fa8-a726-4227744845c1', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 36, 36, 'But if any man thinks that he is behaving inappropriately toward his virgin, if she is past the flower of her age, and if need so requires, let him do what he desires. He doesn''t sin. Let them marry.'),
  ('0ada1439-dcb6-57b4-ae94-28603133a92d', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 37, 37, 'But he who stands steadfast in his heart, having no necessity, but has power over his own heart, to keep his own virgin, does well.'),
  ('b87aa845-841a-5c0e-a1a1-7071220cf7ae', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 38, 38, 'So then both he who gives his own virgin in marriage does well, and he who doesn''t give her in marriage does better.'),
  ('41a9648b-931d-518c-a25d-9f9a38d64140', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 39, 39, 'A wife is bound by law for as long as her husband lives; but if the husband is dead, she is free to be married to whoever she desires, only in the Lord.'),
  ('dbd78012-d6d7-5b1d-a736-c86a2bb0528e', '4f55e76b-0c6b-533e-a910-330333d292fc', NULL, 40, 40, 'But she is happier if she stays as she is, in my judgment, and I think that I also have God''s Spirit.'),
  ('c8de36b6-377e-5b5f-a3cc-7740d92e5d86', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 1, 1, 'Now concerning things sacrificed to idols: We know that we all have knowledge. Knowledge puffs up, but love builds up.'),
  ('06959622-d0b6-5a05-adda-51fa4cfa7916', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 2, 2, 'But if anyone thinks that he knows anything, he doesn''t yet know as he ought to know.'),
  ('f3fe8be2-8750-5ba5-a7b2-59641c67c6eb', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 3, 3, 'But if anyone loves God, the same is known by him.'),
  ('f76732b9-ef97-5188-a439-f150441dd875', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 4, 4, 'Therefore concerning the eating of things sacrificed to idols, we know that no idol is anything in the world, and that there is no other God but one.'),
  ('89968963-aafe-58ab-af9e-f2fa742875ab', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 5, 5, 'For though there are things that are called "gods," whether in the heavens or on earth; as there are many "gods" and many "lords;"'),
  ('1b8d0907-8735-512d-abcd-28d0e74d4e2e', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 6, 6, 'yet to us there is one God, the Father, of whom are all things, and we for him; and one Lord, Jesus Christ, through whom are all things, and we live through him.'),
  ('1158a02e-7c30-5f01-ad00-53e5a48c8e68', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 7, 7, 'However, that knowledge isn''t in all men. But some, with consciousness of the idol until now, eat as of a thing sacrificed to an idol, and their conscience, being weak, is defiled.'),
  ('5fac0526-022b-5cc6-a9ee-dae0ff32033f', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 8, 8, 'But food will not commend us to God. For neither, if we don''t eat, are we the worse; nor, if we eat, are we the better.'),
  ('f4f970a4-c80d-52cb-ae43-1692dd2881f4', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 9, 9, 'But be careful that by no means does this liberty of yours become a stumbling block to the weak.'),
  ('92527c1d-ec3f-5904-a8eb-612c1767caec', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 10, 10, 'For if a man sees you who have knowledge sitting in an idol''s temple, won''t his conscience, if he is weak, be emboldened to eat things sacrificed to idols?'),
  ('74831990-100e-58a1-a34f-694325b842ab', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 11, 11, 'And through your knowledge, he who is weak perishes, the brother for whose sake Christ died.'),
  ('3cc82b84-62ae-5cf3-a1c5-ce373817c194', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 12, 12, 'Thus, sinning against the brothers, and wounding their conscience when it is weak, you sin against Christ.'),
  ('e4e85144-3763-54d5-ac69-0929578b7aa3', '661406b8-7564-5947-a8e4-fc1dadb27b91', NULL, 13, 13, 'Therefore, if food causes my brother to stumble, I will eat no meat forevermore, that I don''t cause my brother to stumble.'),
  ('6e995e1a-f61c-5b5f-a498-1535756ac563', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 1, 1, 'Am I not free? Am I not an apostle? Haven''t I seen Jesus Christ, our Lord? Aren''t you my work in the Lord?'),
  ('3ac4d12c-2a3c-5a6d-afb4-cd3245c405d4', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 2, 2, 'If to others I am not an apostle, yet at least I am to you; for you are the seal of my apostleship in the Lord.'),
  ('96c79b8d-d272-52b4-a000-2275430af5aa', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 3, 3, 'My defense to those who examine me is this.'),
  ('28b8b713-a658-549f-aded-db718a3e2537', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 4, 4, 'Have we no right to eat and to drink?'),
  ('40494075-1ff2-53b4-aece-9cb9485329ce', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 5, 5, 'Have we no right to take along a wife who is a believer, even as the rest of the apostles, and the brothers of the Lord, and Cephas?'),
  ('02f962ae-4c40-5709-aca6-505ca83d77d4', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 6, 6, 'Or have only Barnabas and I no right to not work?'),
  ('44871be0-fc0c-59a2-a889-e0c2240480de', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 7, 7, 'What soldier ever serves at his own expense? Who plants a vineyard, and doesn''t eat of its fruit? Or who feeds a flock, and doesn''t drink from the flock''s milk?'),
  ('571ec35a-3b0b-5634-adc3-b7f0a2de25fa', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 8, 8, 'Do I speak these things according to the ways of men? Or doesn''t the law also say the same thing?'),
  ('fdfeb25d-a6a6-514a-aa76-c6ca9e7f7f13', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 9, 9, 'For it is written in the law of Moses, "You shall not muzzle an ox while it treads out the grain." Is it for the oxen that God cares,'),
  ('25bc1d95-9103-57b3-a43c-66de17f281c0', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 10, 10, 'or does he say it assuredly for our sake? Yes, it was written for our sake, because he who plows ought to plow in hope, and he who threshes in hope should partake of his hope.'),
  ('f81ad9e0-f763-58a5-ae99-ae71b8c7806c', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 11, 11, 'If we sowed to you spiritual things, is it a great thing if we reap your fleshly things?'),
  ('0306cde9-39c3-5a5b-a939-d85958cfe859', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 12, 12, 'If others partake of this right over you, don''t we yet more? Nevertheless we did not use this right, but we bear all things, that we may cause no hindrance to the Good News of Christ.'),
  ('07314a18-0e8c-5453-ae4d-a38d8e9aab24', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 13, 13, 'Don''t you know that those who serve around sacred things eat from the things of the temple, and those who wait on the altar have their portion with the altar?'),
  ('3a7dec40-2a78-5ee2-a391-fee21774fd84', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 14, 14, 'Even so the Lord ordained that those who proclaim the Good News should live from the Good News.'),
  ('b73bf91f-6593-5101-a4cc-29de9ccbbf9a', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 15, 15, 'But I have used none of these things, and I don''t write these things that it may be done so in my case; for I would rather die, than that anyone should make my boasting void.'),
  ('e719e43b-2f32-58ac-a53b-365c85458f30', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 16, 16, 'For if I preach the Good News, I have nothing to boast about; for necessity is laid on me; but woe is to me, if I don''t preach the Good News.'),
  ('ca9b7fb8-06dc-563f-aab0-1389c530bf83', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 17, 17, 'For if I do this of my own will, I have a reward. But if not of my own will, I have a stewardship entrusted to me.'),
  ('ef7cc20f-6ed7-55d7-ab6d-de6fd8f38121', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 18, 18, 'What then is my reward? That, when I preach the Good News, I may present the Good News of Christ without charge, so as not to abuse my authority in the Good News.'),
  ('508f4147-9350-5ec7-aefd-410a76112a70', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 19, 19, 'For though I was free from all, I brought myself under bondage to all, that I might gain the more.'),
  ('54dde0e7-0bb5-50ef-af15-6a04b7fc3a34', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 20, 20, 'To the Jews I became as a Jew, that I might gain Jews; to those who are under the law, as under the law, that I might gain those who are under the law;'),
  ('5e1854c5-d697-5c9e-ac4e-c3c9206a1c51', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 21, 21, 'to those who are without law, as without law (not being without law toward God, but under law toward Christ), that I might win those who are without law.'),
  ('7d46420c-a70b-51d7-ac7b-a261a83fec3d', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 22, 22, 'To the weak I became as weak, that I might gain the weak. I have become all things to all men, that I may by all means save some.'),
  ('0b07e4b1-cb1f-5ba2-a5aa-a6233555517a', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 23, 23, 'Now I do this for the sake of the Good News, that I may be a joint partaker of it.'),
  ('40f1c87e-00fd-55ed-af3b-b55094e71687', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 24, 24, 'Don''t you know that those who run in a race all run, but one receives the prize? Run like that, that you may win.'),
  ('f5a5ad50-09c8-58c7-a5bb-712fd039e8e3', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 25, 25, 'Every man who strives in the games exercises self-control in all things. Now they do it to receive a corruptible crown, but we an incorruptible.'),
  ('3762af72-2df3-59db-acc8-f304bfbfce9c', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 26, 26, 'I therefore run like that, as not uncertainly. I fight like that, as not beating the air,'),
  ('78ba77b6-3f5e-5ed2-a1f5-c8b0ba7e9a99', '1c6b8915-5898-5a4e-a220-26f09354fc47', NULL, 27, 27, 'but I beat my body and bring it into submission, lest by any means, after I have preached to others, I myself should be rejected.'),
  ('2b36d89a-a343-5ce6-a53e-8f0c6204a743', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 1, 1, 'Now I would not have you ignorant, brothers, that our fathers were all under the cloud, and all passed through the sea;'),
  ('6e0ecd3e-e3d4-500d-a5cc-841d77b5517e', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 2, 2, 'and were all baptized into Moses in the cloud and in the sea;'),
  ('78a350ef-f812-5c42-a392-34adb8039e38', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 3, 3, 'and all ate the same spiritual food;'),
  ('0a33ec6e-c08e-53f7-aa16-a3e2a1d34694', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 4, 4, 'and all drank the same spiritual drink. For they drank of a spiritual rock that followed them, and the rock was Christ.'),
  ('13643345-51dc-5afa-a41b-0edf64336a62', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 5, 5, 'However with most of them, God was not well pleased, for they were overthrown in the wilderness.'),
  ('53ac2d27-b066-5225-abbd-cc7fbde82a1b', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 6, 6, 'Now these things were our examples, to the intent we should not lust after evil things, as they also lusted.'),
  ('0c72906b-2ce5-5abc-a6b0-f62f831e2940', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 7, 7, 'Neither be idolaters, as some of them were. As it is written, "The people sat down to eat and drink, and rose up to play."'),
  ('ed4cbcde-bbb1-5ddc-a89d-295fa7b09b11', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 8, 8, 'Neither let us commit sexual immorality, as some of them committed, and in one day twenty-three thousand fell.'),
  ('6b8e05d9-e94a-5613-a860-e616bec62e38', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 9, 9, 'Neither let us test the Lord, as some of them tested, and perished by the serpents.'),
  ('d2a3564b-03ec-591a-a73d-380d3e459e8b', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 10, 10, 'Neither grumble, as some of them also grumbled, and perished by the destroyer.'),
  ('4d1f4cd9-d7f9-587a-a43f-cbbeb3eb2125', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 11, 11, 'Now all these things happened to them by way of example, and they were written for our admonition, on whom the ends of the ages have come.'),
  ('5d330828-a1ee-594e-a1b4-31b00b198a5a', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 12, 12, 'Therefore let him who thinks he stands be careful that he doesn''t fall.'),
  ('234ffc4c-ff80-576b-a8e9-9e506e03632c', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 13, 13, 'No temptation has taken you except what is common to man. God is faithful, who will not allow you to be tempted above what you are able, but will with the temptation also make the way of escape, that you may be able to endure it.'),
  ('f1cce6ed-0f83-5df0-a471-746248d8b1a2', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 14, 14, 'Therefore, my beloved, flee from idolatry.'),
  ('fdbaee54-cd5f-51be-ae25-eb6bf9f9a5ce', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 15, 15, 'I speak as to wise men. Judge what I say.'),
  ('c2a1cf95-4036-54db-a058-3d115542bd0c', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 16, 16, 'The cup of blessing which we bless, isn''t it a sharing of the blood of Christ? The bread which we break, isn''t it a sharing of the body of Christ?'),
  ('7cd91a08-560d-5dee-ad55-3b625f8f5079', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 17, 17, 'Because there is one loaf of bread, we, who are many, are one body; for we all partake of the one loaf of bread.'),
  ('fae9ff01-5827-5837-a6c9-f288b9c482c8', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 18, 18, 'Consider Israel according to the flesh. Don''t those who eat the sacrifices participate in the altar?'),
  ('251a91cd-2635-5be3-af2a-4f89324971f8', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 19, 19, 'What am I saying then? That a thing sacrificed to idols is anything, or that an idol is anything?'),
  ('1e6702ae-2920-591e-a7c0-4dcf9d179afd', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 20, 20, 'But I say that the things which the Gentiles sacrifice, they sacrifice to demons, and not to God, and I don''t desire that you would have fellowship with demons.'),
  ('c5577938-d030-5a0c-a1a7-86b6f557f1dc', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 21, 21, 'You can''t both drink the cup of the Lord and the cup of demons. You can''t both partake of the table of the Lord, and of the table of demons.'),
  ('13c748a7-3104-52d4-ab21-0efa18500022', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 22, 22, 'Or do we provoke the Lord to jealousy? Are we stronger than he?'),
  ('ea4bc59a-4e9e-5127-a2c1-ade5d9bcadc2', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 23, 23, '"All things are lawful for me," but not all things are profitable. "All things are lawful for me," but not all things build up.'),
  ('220d86b7-238d-5b03-a811-ec9ad8b2067a', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 24, 24, 'Let no one seek his own, but each one his neighbor''s good.'),
  ('57de23d9-bd36-5c15-a6ea-68000abdf1fa', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 25, 25, 'Whatever is sold in the butcher shop, eat, asking no question for the sake of conscience,'),
  ('af1ae3c9-ea58-5430-a3c7-588f5c79edf6', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 26, 26, 'for "the earth is the Lord''s, and its fullness."'),
  ('92ba2354-4415-5f2a-a405-c5c11ea737e0', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 27, 27, 'But if one of those who don''t believe invites you to a meal, and you are inclined to go, eat whatever is set before you, asking no questions for the sake of conscience.'),
  ('f90a9ab7-3902-5425-a034-c76adacd2553', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 28, 28, 'But if anyone says to you, "This was offered to idols," don''t eat it for the sake of the one who told you, and for the sake of conscience. For "the earth is the Lord''s, and all its fullness."'),
  ('92fe2363-c426-5dba-a2a3-486626fd7b68', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 29, 29, 'Conscience, I say, not your own, but the other''s conscience. For why is my liberty judged by another conscience?'),
  ('47e1f3f1-012f-514f-aa9d-06b3ead85d27', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 30, 30, 'If I partake with thankfulness, why am I denounced for that for which I give thanks?'),
  ('32d896a0-5f44-57ab-af00-a5a1773e1d27', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 31, 31, 'Whether therefore you eat, or drink, or whatever you do, do all to the glory of God.'),
  ('db064a8b-c373-5936-a0a6-3715dfea8ed9', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 32, 32, 'Give no occasions for stumbling, either to Jews, or to Greeks, or to the assembly of God;'),
  ('9cb124cb-4658-5f93-a5b9-e97247e53b90', 'c7ab5ec1-a179-5b9e-a5c4-bb557b1bcd57', NULL, 33, 33, 'even as I also please all men in all things, not seeking my own profit, but the profit of the many, that they may be saved.'),
  ('15a8de8d-0ac4-5b53-a2a2-ea1b57d6f572', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 1, 1, 'Be imitators of me, even as I also am of Christ.'),
  ('4fd60301-59ce-5372-a16e-007375b0e021', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 2, 2, 'Now I praise you, brothers, that you remember me in all things, and hold firm the traditions, even as I delivered them to you.'),
  ('5505a0e7-2106-519e-a027-e959dedef9bb', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 3, 3, 'But I would have you know that the head of every man is Christ, and the head of the woman is the man, and the head of Christ is God.'),
  ('703e91ce-805b-56aa-a9df-66b87343df8b', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 4, 4, 'Every man praying or prophesying, having his head covered, dishonors his head.'),
  ('0123eafc-b278-5960-a15d-feb853d2c8c7', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 5, 5, 'But every woman praying or prophesying with her head unveiled dishonors her head. For it is one and the same thing as if she were shaved.'),
  ('6454d6d8-1287-5665-ae83-f4876c13807e', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 6, 6, 'For if a woman is not covered, let her also be shorn. But if it is shameful for a woman to be shorn or shaved, let her be covered.'),
  ('25d6d26e-a2ff-5410-adde-d769ba571ff6', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 7, 7, 'For a man indeed ought not to have his head covered, because he is the image and glory of God, but the woman is the glory of the man.'),
  ('a412f9e4-5bd4-5283-af88-3ff5a7b037fe', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 8, 8, 'For man is not from woman, but woman from man;'),
  ('a49b528c-11c6-5fac-a87f-6a6a12ba47a8', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 9, 9, 'for neither was man created for the woman, but woman for the man.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('4e1dfa36-8f0e-5103-ae25-cb5258feecd7', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 10, 10, 'For this cause the woman ought to have authority on her head, because of the angels.'),
  ('6416f40e-d592-546d-a4ee-370a15fb51b4', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 11, 11, 'Nevertheless, neither is the woman independent of the man, nor the man independent of the woman, in the Lord.'),
  ('1fdee1bd-e4ff-5633-a269-6cf144f6449d', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 12, 12, 'For as woman came from man, so a man also comes through a woman; but all things are from God.'),
  ('469a7b98-26d6-5c26-a9be-0a0ada6e46ee', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 13, 13, 'Judge for yourselves. Is it appropriate that a woman pray to God unveiled?'),
  ('4d41dd3b-048b-5cde-a69b-121ff8cb7861', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 14, 14, 'Doesn''t even nature itself teach you that if a man has long hair, it is a dishonor to him?'),
  ('af269f5e-783c-54e8-af02-939bddc32b85', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 15, 15, 'But if a woman has long hair, it is a glory to her, for her hair is given to her for a covering.'),
  ('42a69149-2f86-5036-a971-9e61a07fe0f0', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 16, 16, 'But if any man seems to be contentious, we have no such custom, neither do God''s assemblies.'),
  ('66208ce0-6692-50f6-a68a-cb7fea2acb97', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 17, 17, 'But in giving you this command, I don''t praise you, that you come together not for the better but for the worse.'),
  ('f7494a35-6dc3-5041-ae6d-d7d9a5c0eae1', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 18, 18, 'For first of all, when you come together in the assembly, I hear that divisions exist among you, and I partly believe it.'),
  ('f8785674-23e8-5408-aa08-bb2b157d8842', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 19, 19, 'For there also must be factions among you, that those who are approved may be revealed among you.'),
  ('097adbcb-a573-564d-a1fa-9aaae72ef636', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 20, 20, 'When therefore you assemble yourselves together, it is not the Lord''s supper that you eat.'),
  ('b815e289-1e93-5cc9-a98e-cb0293ed9c37', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 21, 21, 'For in your eating each one takes his own supper first. One is hungry, and another is drunken.'),
  ('f7673b2d-cda1-5177-a18e-ef21950b2f55', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 22, 22, 'What, don''t you have houses to eat and to drink in? Or do you despise God''s assembly, and put them to shame who don''t have? What shall I tell you? Shall I praise you? In this I don''t praise you.'),
  ('99a5d16c-042b-52c8-a4c7-293964588c75', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 23, 23, 'For I received from the Lord that which also I delivered to you, that the Lord Jesus on the night in which he was betrayed took bread.'),
  ('696ea604-1198-5047-acd5-14a54e75fb53', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 24, 24, 'When he had given thanks, he broke it, and said, "Take, eat. This is my body, which is broken for you. Do this in memory of me."'),
  ('4e0fb1a1-fdea-5c43-ab5b-20e9725705a2', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 25, 25, 'In the same way he also took the cup, after supper, saying, "This cup is the new covenant in my blood. Do this, as often as you drink, in memory of me."'),
  ('b695105f-6a1d-565c-a06b-0fb1c5b3c5c2', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 26, 26, 'For as often as you eat this bread and drink this cup, you proclaim the Lord''s death until he comes.'),
  ('4fb21461-4def-58b1-a4da-1c9460fc41eb', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 27, 27, 'Therefore whoever eats this bread or drinks the Lord''s cup in a way unworthy of the Lord will be guilty of the body and the blood of the Lord.'),
  ('199052a0-47a0-5eb6-a53d-1eebec191017', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 28, 28, 'But let a man examine himself, and so let him eat of the bread, and drink of the cup.'),
  ('4b96b6f5-6742-5ada-a14e-38b095bd884e', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 29, 29, 'For he who eats and drinks in an unworthy way eats and drinks judgment to himself, if he doesn''t discern the Lord''s body.'),
  ('55724d13-65a5-5717-a0ac-89a12a74ef51', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 30, 30, 'For this cause many among you are weak and sickly, and not a few sleep.'),
  ('edc6451a-cff8-5b0d-a32a-7a80f42eaba1', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 31, 31, 'For if we discerned ourselves, we wouldn''t be judged.'),
  ('24e49e86-b57a-5539-a452-2142c4348804', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 32, 32, 'But when we are judged, we are punished by the Lord, that we may not be condemned with the world.'),
  ('44485fcd-8a1c-58f6-adc3-fa447c7b4864', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 33, 33, 'Therefore, my brothers, when you come together to eat, wait for one another.'),
  ('a0f22bbd-8adf-5695-a792-b67cce1b307e', '2a413895-6c11-5e67-a8f4-abf99f7f2241', NULL, 34, 34, 'But if anyone is hungry, let him eat at home, lest your coming together be for judgment. The rest I will set in order whenever I come.'),
  ('4c72db32-b310-52e5-a31a-2a145bc5a368', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 1, 1, 'Now concerning spiritual things, brothers, I don''t want you to be ignorant.'),
  ('698430f9-f91b-50f9-a029-d27529d6e57c', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 2, 2, 'You know that when you were heathen, you were led away to those mute idols, however you might be led.'),
  ('176cd3d9-85e5-55a0-a66b-e783b412ee92', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 3, 3, 'Therefore I make known to you that no man speaking by God''s Spirit says, "Jesus is accursed." No one can say, "Jesus is Lord," but by the Holy Spirit.'),
  ('68e334e8-c8ca-52e6-a21a-c3c749388bdc', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 4, 4, 'Now there are various kinds of gifts, but the same Spirit.'),
  ('2bc1b564-5758-5fcb-aea6-1c2dd401273f', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 5, 5, 'There are various kinds of service, and the same Lord.'),
  ('f4891d78-1141-5faf-add9-f92bf3866f6e', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 6, 6, 'There are various kinds of workings, but the same God, who works all things in all.'),
  ('d9462fd4-7ed8-50eb-a40d-5fc467eb424e', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 7, 7, 'But to each one is given the manifestation of the Spirit for the profit of all.'),
  ('df0228ea-2dfd-5387-a61f-708117f4790a', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 8, 8, 'For to one is given through the Spirit the word of wisdom, and to another the word of knowledge, according to the same Spirit;'),
  ('d6306aaa-cb25-59a6-a7ab-97ea206de91d', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 9, 9, 'to another faith, by the same Spirit; and to another gifts of healings, by the same Spirit;'),
  ('f2da4be5-32bf-5a53-a6a6-c286949e77db', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 10, 10, 'and to another workings of miracles; and to another prophecy; and to another discerning of spirits; to another different kinds of languages; and to another the interpretation of languages.'),
  ('2c7d7a39-4fc7-52fe-aa84-aef3548cfcee', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 11, 11, 'But the one and the same Spirit works all of these, distributing to each one separately as he desires.'),
  ('8726b210-e005-5c59-a15c-c0ec983eb70e', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 12, 12, 'For as the body is one, and has many members, and all the members of the body, being many, are one body; so also is Christ.'),
  ('4d24b47b-d8d0-51af-a9f2-e03fc222d359', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 13, 13, 'For in one Spirit we were all baptized into one body, whether Jews or Greeks, whether bond or free; and were all given to drink into one Spirit.'),
  ('602ee1bc-414d-5d22-a591-eb56e9e667cb', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 14, 14, 'For the body is not one member, but many.'),
  ('0888ddb8-7169-53aa-a419-3a12dfc1ddf5', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 15, 15, 'If the foot would say, "Because I''m not the hand, I''m not part of the body," it is not therefore not part of the body.'),
  ('11b2f4bc-7751-564b-a05f-82999441ce58', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 16, 16, 'If the ear would say, "Because I''m not the eye, I''m not part of the body," it''s not therefore not part of the body.'),
  ('617f02f1-d323-569f-ad57-24cbdc5e4790', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 17, 17, 'If the whole body were an eye, where would the hearing be? If the whole were hearing, where would the smelling be?'),
  ('29b79471-710f-5bd6-a082-0c80906c0abe', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 18, 18, 'But now God has set the members, each one of them, in the body, just as he desired.'),
  ('ed09bf0d-90bd-561c-afe4-2dd63a0e3327', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 19, 19, 'If they were all one member, where would the body be?'),
  ('25bf0e16-3ad0-5b2d-aca3-146c28fcc61a', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 20, 20, 'But now they are many members, but one body.'),
  ('cf26d50f-b94b-5429-a2fd-e680b557a21b', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 21, 21, 'The eye can''t tell the hand, "I have no need for you," or again the head to the feet, "I have no need for you."'),
  ('3881e75e-6396-50c5-a92e-8e53b6c15007', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 22, 22, 'No, much rather, those members of the body which seem to be weaker are necessary.'),
  ('ab59c3c1-f78d-5c3d-a56f-c48dc7b00a46', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 23, 23, 'Those parts of the body which we think to be less honorable, on those we bestow more abundant honor; and our unpresentable parts have more abundant propriety;'),
  ('09679230-75fb-5eb9-af90-900c24a97376', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 24, 24, 'whereas our presentable parts have no such need. But God composed the body together, giving more abundant honor to the inferior part,'),
  ('fe634748-1e06-534b-ac55-b4cac0c7b1ee', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 25, 25, 'that there should be no division in the body, but that the members should have the same care for one another.'),
  ('4d1af28d-0890-5d45-ad3c-232731e5c302', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 26, 26, 'When one member suffers, all the members suffer with it. Or when one member is honored, all the members rejoice with it.'),
  ('35eadd71-8037-5428-ac49-a798a5121b68', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 27, 27, 'Now you are the body of Christ, and members individually.'),
  ('6c3362f2-e458-513e-a177-9c8a53cc7e07', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 28, 28, 'God has set some in the assembly: first apostles, second prophets, third teachers, then miracle workers, then gifts of healings, helps, governments, and various kinds of languages.'),
  ('c5ece6d4-73cb-565b-a40b-364a844a3918', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 29, 29, 'Are all apostles? Are all prophets? Are all teachers? Are all miracle workers?'),
  ('092dc92b-d92d-53de-a58c-8fe55c6ac7bf', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 30, 30, 'Do all have gifts of healings? Do all speak with various languages? Do all interpret?'),
  ('1b2781e6-f173-5a46-a2af-3aacd6f4c095', 'f4276578-4af2-541f-ab6c-24f74b66e5de', NULL, 31, 31, 'But earnestly desire the best gifts. Moreover, I show a most excellent way to you.'),
  ('cfad94c1-1b5e-5eed-aad4-5b2f80a929e7', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 1, 1, 'If I speak with the languages of men and of angels, but don''t have love, I have become sounding brass, or a clanging cymbal.'),
  ('7b1d2183-e132-5bfc-a811-d069e2b23af7', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 2, 2, 'If I have the gift of prophecy, and know all mysteries and all knowledge; and if I have all faith, so as to remove mountains, but don''t have love, I am nothing.'),
  ('73f0fda3-7455-5dfb-adbc-412626ada587', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 3, 3, 'If I dole out all my goods to feed the poor, and if I give my body to be burned, but don''t have love, it profits me nothing.'),
  ('aabcc45b-02ef-586c-ad7d-36a8f8c1ceb4', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 4, 4, 'Love is patient and is kind; love doesn''t envy. Love doesn''t brag, is not proud,'),
  ('42b57e7f-f634-5fdc-a82d-06d709eada0a', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 5, 5, 'doesn''t behave itself inappropriately, doesn''t seek its own way, is not provoked, takes no account of evil;'),
  ('8af260af-1b79-5976-ab04-6b603fb89090', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 6, 6, 'doesn''t rejoice in unrighteousness, but rejoices with the truth;'),
  ('62ea6893-d9b1-5ae8-a389-423ee64c4518', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 7, 7, 'bears all things, believes all things, hopes all things, endures all things.'),
  ('23598241-dc43-5d9b-ad6d-90a07ba73955', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 8, 8, 'Love never fails. But where there are prophecies, they will be done away with. Where there are various languages, they will cease. Where there is knowledge, it will be done away with.'),
  ('91a338fb-d7ad-5397-a9b3-9c033e982b37', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 9, 9, 'For we know in part, and we prophesy in part;'),
  ('83d6e738-fa9c-5e73-a2ae-f2399713d2f7', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 10, 10, 'but when that which is complete has come, then that which is partial will be done away with.'),
  ('4a0fe999-0b79-5267-a200-76f9b163c57c', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 11, 11, 'When I was a child, I spoke as a child, I felt as a child, I thought as a child. Now that I have become a man, I have put away childish things.'),
  ('d68c6f45-3038-5982-a8e5-7ee1c2a45545', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 12, 12, 'For now we see in a mirror, dimly, but then face to face. Now I know in part, but then I will know fully, even as I was also fully known.'),
  ('59ee6098-b9c7-521f-a208-e6066e982cef', 'fc3bbc2e-84d0-5767-a09c-b9ce0cfbcf32', NULL, 13, 13, 'But now faith, hope, and love remain--these three. The greatest of these is love.'),
  ('a0a05894-1403-5042-a52f-6b4c7b60cca7', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 1, 1, 'Follow after love, and earnestly desire spiritual gifts, but especially that you may prophesy.'),
  ('fed0f65d-cc93-5255-a203-e8aeb49f551c', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 2, 2, 'For he who speaks in another language speaks not to men, but to God; for no one understands; but in the Spirit he speaks mysteries.'),
  ('1e423c23-9206-5046-a027-d1726710350d', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 3, 3, 'But he who prophesies speaks to men for their edification, exhortation, and consolation.'),
  ('98b7d2c3-fc3f-5f59-a669-4c1733677160', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 4, 4, 'He who speaks in another language edifies himself, but he who prophesies edifies the assembly.'),
  ('58623453-1dcd-5d1b-a23a-eae825a0c531', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 5, 5, 'Now I desire to have you all speak with other languages, but rather that you would prophesy. For he is greater who prophesies than he who speaks with other languages, unless he interprets, that the assembly may be built up.'),
  ('565fa927-a29b-586a-a39a-3196fdf54404', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 6, 6, 'But now, brothers, if I come to you speaking with other languages, what would I profit you, unless I speak to you either by way of revelation, or of knowledge, or of prophesying, or of teaching?'),
  ('8a61c502-e3ab-5505-a114-9b1161e29730', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 7, 7, 'Even things without life, giving a voice, whether pipe or harp, if they didn''t give a distinction in the sounds, how would it be known what is piped or harped?'),
  ('a148f567-c69a-55f6-a3d3-82a192a47acd', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 8, 8, 'For if the trumpet gave an uncertain sound, who would prepare himself for war?'),
  ('6737b368-64cc-5912-a7b2-afe3526b93c9', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 9, 9, 'So also you, unless you uttered by the tongue words easy to understand, how would it be known what is spoken? For you would be speaking into the air.'),
  ('9aa8ccad-0e15-5039-aaa5-ee34ecb8eb1c', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 10, 10, 'There are, it may be, so many kinds of sounds in the world, and none of them is without meaning.'),
  ('d4c0fd40-e334-5fbd-a7ee-6a0a75445420', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 11, 11, 'If then I don''t know the meaning of the sound, I would be to him who speaks a foreigner, and he who speaks would be a foreigner to me.'),
  ('9c9721e8-52d5-55fa-ac61-9bbe6851324e', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 12, 12, 'So also you, since you are zealous for spiritual gifts, seek that you may abound to the building up of the assembly.'),
  ('c9013a19-50d1-5784-a4ee-bc237fa519da', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 13, 13, 'Therefore let him who speaks in another language pray that he may interpret.'),
  ('d6236010-eb93-5abe-ac6c-0584302a138c', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 14, 14, 'For if I pray in another language, my spirit prays, but my understanding is unfruitful.'),
  ('51271e6c-f8f5-5d1f-a746-394d9ef9482f', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 15, 15, 'What is it then? I will pray with the spirit, and I will pray with the understanding also. I will sing with the spirit, and I will sing with the understanding also.'),
  ('99c8b9fa-a3d0-5eb9-a551-0d34dc265227', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 16, 16, 'Otherwise if you bless with the spirit, how will he who fills the place of the unlearned say the "Amen" at your giving of thanks, seeing he doesn''t know what you say?'),
  ('50ce11d6-674b-55ff-a5fd-a4b5876a1985', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 17, 17, 'For you most certainly give thanks well, but the other person is not built up.'),
  ('7ec92007-fa74-59fc-a852-4210581b6479', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 18, 18, 'I thank my God, I speak with other languages more than you all.'),
  ('29ee07ff-ff39-50b8-a3b9-c97376fd03e3', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 19, 19, 'However in the assembly I would rather speak five words with my understanding, that I might instruct others also, than ten thousand words in another language.'),
  ('56131fc7-5715-5906-a2d8-091759f75f76', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 20, 20, 'Brothers, don''t be children in thoughts, yet in malice be babies, but in thoughts be mature.'),
  ('cdf3bc0d-9046-5dbc-ae6d-65dc5c595daa', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 21, 21, 'In the law it is written, "By men of strange languages and by the lips of strangers I will speak to this people. Not even thus will they hear me, says the Lord."'),
  ('1f87a605-c977-5351-ad09-6269222d851a', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 22, 22, 'Therefore other languages are for a sign, not to those who believe, but to the unbelieving; but prophesying is for a sign, not to the unbelieving, but to those who believe.'),
  ('c812e0b4-c704-570d-a620-72d86ab88d58', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 23, 23, 'If therefore the whole assembly is assembled together and all speak with other languages, and unlearned or unbelieving people come in, won''t they say that you are crazy?'),
  ('4c74df11-6173-536e-afdc-b698fe776370', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 24, 24, 'But if all prophesy, and someone unbelieving or unlearned comes in, he is reproved by all, and he is judged by all.'),
  ('6e6c44f5-b080-59e7-a098-7bd5c27966ab', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 25, 25, 'And thus the secrets of his heart are revealed. So he will fall down on his face and worship God, declaring that God is among you indeed.'),
  ('85028451-013a-5213-a246-6a3ae519bced', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 26, 26, 'What is it then, brothers? When you come together, each one of you has a psalm, has a teaching, has a revelation, has another language, has an interpretation. Let all things be done to build each other up.'),
  ('4dc21fe2-2671-521d-ad4d-e12679797765', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 27, 27, 'If any man speaks in another language, let it be two, or at the most three, and in turn; and let one interpret.'),
  ('268857c7-5074-5e09-a7f8-005c217fab95', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 28, 28, 'But if there is no interpreter, let him keep silent in the assembly, and let him speak to himself, and to God.'),
  ('aa7f5b3d-b41e-534a-a6ca-b37e7992bd50', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 29, 29, 'Let the prophets speak, two or three, and let the others discern.'),
  ('7371065f-61e9-50c9-a337-3a6e82844161', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 30, 30, 'But if a revelation is made to another sitting by, let the first keep silent.'),
  ('1a41e85a-b072-58ab-a28a-99cad550a067', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 31, 31, 'For you all can prophesy one by one, that all may learn, and all may be exhorted.'),
  ('a67d9631-821b-5204-a0af-843a59061a43', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 32, 32, 'The spirits of the prophets are subject to the prophets,'),
  ('3c73e6fc-66ea-5202-aae7-7f92bc8a4007', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 33, 33, 'for God is not a God of confusion, but of peace. As in all the assemblies of the saints,'),
  ('e3917252-9a40-5509-a7db-074f54f6fe03', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 34, 34, 'let your wives keep silent in the assemblies, for it has not been permitted for them to speak; but let them be in subjection, as the law also says.'),
  ('99e8d4f6-efcc-598b-aca3-22c96ceedb53', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 35, 35, 'If they desire to learn anything, let them ask their own husbands at home, for it is shameful for a woman to chatter in the assembly.'),
  ('9afefcf2-8450-5b56-a650-0d84e9e67a2a', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 36, 36, 'What? Was it from you that the word of God went out? Or did it come to you alone?'),
  ('443be699-82eb-57c7-accc-df034bfaf52d', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 37, 37, 'If any man thinks himself to be a prophet, or spiritual, let him recognize the things which I write to you, that they are the commandment of the Lord.'),
  ('9a960302-9082-5363-acf3-e5b48700ffc1', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 38, 38, 'But if anyone is ignorant, let him be ignorant.'),
  ('13b3545f-4798-5076-a803-c02abca96a91', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 39, 39, 'Therefore, brothers, desire earnestly to prophesy, and don''t forbid speaking with other languages.'),
  ('3e2859ee-e853-5145-a237-75a34fc1cc88', 'df37b8a0-9a26-5100-a01e-15f5d006a1ab', NULL, 40, 40, 'Let all things be done decently and in order.'),
  ('c2fe0e7d-32ae-52fe-ad0c-f54c617bd16e', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 1, 1, 'Now I declare to you, brothers, the Good News which I preached to you, which also you received, in which you also stand,'),
  ('54f7063b-af9b-5e08-a09c-4e86feff829f', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 2, 2, 'by which also you are saved, if you hold firmly the word which I preached to you--unless you believed in vain.'),
  ('7a746ed1-c2bb-5343-a5f3-ba2f00bd6d8a', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 3, 3, 'For I delivered to you first of all that which I also received: that Christ died for our sins according to the Scriptures,'),
  ('a47d9c34-25b0-5b28-a301-e0d7870e4cb3', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 4, 4, 'that he was buried, that he was raised on the third day according to the Scriptures,'),
  ('06781dd6-00f8-5a7a-a1d4-140c70767717', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 5, 5, 'and that he appeared to Cephas, then to the twelve.'),
  ('5197dfbe-ed39-519d-a5e6-86f1a11c53f0', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 6, 6, 'Then he appeared to over five hundred brothers at once, most of whom remain until now, but some have also fallen asleep.'),
  ('a4466887-2cb4-582e-a630-eab84f334f9d', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 7, 7, 'Then he appeared to James, then to all the apostles,'),
  ('90291dab-1090-5c32-aaf2-2ab2037e957d', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 8, 8, 'and last of all, as to the child born at the wrong time, he appeared to me also.'),
  ('535d4cf2-457d-5368-a940-32da96575945', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 9, 9, 'For I am the least of the apostles, who is not worthy to be called an apostle, because I persecuted the assembly of God.'),
  ('223febb0-37e0-534c-a07c-bf2b9f17f308', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 10, 10, 'But by the grace of God I am what I am. His grace which was bestowed on me was not futile, but I worked more than all of them; yet not I, but the grace of God which was with me.'),
  ('f9abf5d3-ec89-55bc-a5b2-d5fc4fa2124c', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 11, 11, 'Whether then it is I or they, so we preach, and so you believed.'),
  ('f0286f9b-cdf1-57a4-abba-52d999ba858b', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 12, 12, 'Now if Christ is preached, that he has been raised from the dead, how do some among you say that there is no resurrection of the dead?'),
  ('04fdd148-d6c9-5443-a270-da27b7c649d4', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 13, 13, 'But if there is no resurrection of the dead, neither has Christ been raised.'),
  ('e0b21d08-1409-5f19-a681-a024d92a388b', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 14, 14, 'If Christ has not been raised, then our preaching is in vain, and your faith also is in vain.'),
  ('6c42ed9a-1eef-503d-aa36-1ee115456f13', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 15, 15, 'Yes, we are found false witnesses of God, because we testified about God that he raised up Christ, whom he didn''t raise up, if it is so that the dead are not raised.'),
  ('67d0cc96-5271-52e9-a204-ba18ec6ef1ca', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 16, 16, 'For if the dead aren''t raised, neither has Christ been raised.'),
  ('36210c8f-2479-588a-a955-d5a9f15d4050', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 17, 17, 'If Christ has not been raised, your faith is vain; you are still in your sins.'),
  ('12573f90-34f2-5eb5-a519-0dbed6416e97', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 18, 18, 'Then they also who are fallen asleep in Christ have perished.'),
  ('92139d9f-2f27-5570-a83e-5e4ae42853bc', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 19, 19, 'If we have only hoped in Christ in this life, we are of all men most pitiable.'),
  ('504753a3-fa88-5405-a85b-e7786417f26c', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 20, 20, 'But now Christ has been raised from the dead. He became the first fruits of those who are asleep.'),
  ('b9d7438f-896a-5eac-a307-a66146be1cf8', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 21, 21, 'For since death came by man, the resurrection of the dead also came by man.'),
  ('d9bad29c-95bf-5e44-a3a7-068bb6fe885e', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 22, 22, 'For as in Adam all die, so also in Christ all will be made alive.'),
  ('053caaa3-2410-5a2f-a155-ede72c872dd8', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 23, 23, 'But each in his own order: Christ the first fruits, then those who are Christ''s, at his coming.'),
  ('24802648-3dc9-5121-ac6a-1d58e4d28a4a', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 24, 24, 'Then the end comes, when he will deliver up the Kingdom to God, even the Father; when he will have abolished all rule and all authority and power.'),
  ('38223204-ee9d-5802-a77d-d2f91d1e8280', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 25, 25, 'For he must reign until he has put all his enemies under his feet.'),
  ('cd9516d4-7776-542e-ad45-2dbfcf14701b', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 26, 26, 'The last enemy that will be abolished is death.'),
  ('65e5a4e3-a427-5174-ac6b-f384559774c4', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 27, 27, 'For, "He put all things in subjection under his feet." But when he says, "All things are put in subjection," it is evident that he is excepted who subjected all things to him.'),
  ('4db896ca-864f-5757-ab39-9867df23f1b8', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 28, 28, 'When all things have been subjected to him, then the Son will also himself be subjected to him who subjected all things to him, that God may be all in all.'),
  ('4e0ddcfc-2a4c-559a-ac04-0567710f47d1', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 29, 29, 'Or else what will they do who are baptized for the dead? If the dead aren''t raised at all, why then are they baptized for the dead?'),
  ('14d13e28-3308-52fa-abac-8e217e11d83c', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 30, 30, 'Why do we also stand in jeopardy every hour?'),
  ('473c3962-37a2-5b9d-a5c3-e5ac515117e5', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 31, 31, 'I affirm, by the boasting in you which I have in Christ Jesus our Lord, I die daily.'),
  ('85a3f9e9-82c0-5228-a9c0-c59d48515f17', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 32, 32, 'If I fought with animals at Ephesus for human purposes, what does it profit me? If the dead are not raised, then "let us eat and drink, for tomorrow we die."'),
  ('97dc6770-cb35-548f-ade2-85e35c19352c', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 33, 33, 'Don''t be deceived! "Evil companionships corrupt good morals."'),
  ('317354d1-9290-579f-a5f6-4083dd73305e', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 34, 34, 'Wake up righteously, and don''t sin, for some have no knowledge of God. I say this to your shame.'),
  ('4e0e76bc-06cb-5d6e-a8a1-049dedcf580a', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 35, 35, 'But someone will say, "How are the dead raised?" and, "With what kind of body do they come?"'),
  ('46ce71a1-6f05-5fb5-a3ea-1cc33742309e', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 36, 36, 'You foolish one, that which you yourself sow is not made alive unless it dies.'),
  ('54663232-aa17-5f1f-adb7-f4ef9f163213', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 37, 37, 'That which you sow, you don''t sow the body that will be, but a bare grain, maybe of wheat, or of some other kind.'),
  ('95a51e29-3666-5cac-a0a7-6d0d86fd1211', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 38, 38, 'But God gives it a body even as it pleased him, and to each seed a body of its own.'),
  ('2482d96e-e299-59ea-aa74-d8fefee76c01', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 39, 39, 'All flesh is not the same flesh, but there is one flesh of men, another flesh of animals, another of fish, and another of birds.'),
  ('35143ccd-bb7c-5a2d-a5dc-eda442d4d036', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 40, 40, 'There are also celestial bodies, and terrestrial bodies; but the glory of the celestial differs from that of the terrestrial.'),
  ('069ebe21-8dab-504c-adae-f2ced55979c0', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 41, 41, 'There is one glory of the sun, another glory of the moon, and another glory of the stars; for one star differs from another star in glory.'),
  ('c7fd7e36-92fd-5a7d-acde-81e9066e6c75', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 42, 42, 'So also is the resurrection of the dead. It is sown in corruption; it is raised in incorruption.'),
  ('19c66bea-fa17-57cd-abcd-0f9ba5df77b1', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 43, 43, 'It is sown in dishonor; it is raised in glory. It is sown in weakness; it is raised in power.'),
  ('0d0ee0b2-b989-5944-a045-dbffb93bb66e', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 44, 44, 'It is sown a natural body; it is raised a spiritual body. There is a natural body and there is also a spiritual body.'),
  ('b4a5b906-a728-5f54-a302-66a2de9f69a3', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 45, 45, 'So also it is written, "The first man, Adam, became a living soul." The last Adam became a life-giving spirit.'),
  ('2ca66abe-90f9-5969-a299-2e669587fd67', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 46, 46, 'However that which is spiritual isn''t first, but that which is natural, then that which is spiritual.'),
  ('7e2100d0-e3f5-5634-a64b-8eb1953e4218', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 47, 47, 'The first man is of the earth, made of dust. The second man is the Lord from heaven.'),
  ('2eefc536-9074-525f-a9bf-ba08bffb2af5', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 48, 48, 'As is the one made of dust, such are those who are also made of dust; and as is the heavenly, such are they also that are heavenly.'),
  ('c2fa5c08-96cf-57bc-a9a8-1c8684a3b157', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 49, 49, 'As we have borne the image of those made of dust, let''s also bear the image of the heavenly.'),
  ('82cb2eec-a3d4-5015-ace4-0a0a130832a0', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 50, 50, 'Now I say this, brothers, that flesh and blood can''t inherit the Kingdom of God; neither does corruption inherit incorruption.'),
  ('62cb3dff-ddba-5dee-ad87-b66fba475072', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 51, 51, 'Behold, I tell you a mystery. We will not all sleep, but we will all be changed,'),
  ('85fb7608-df32-5083-af65-8373cde63552', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 52, 52, 'in a moment, in the twinkling of an eye, at the last trumpet. For the trumpet will sound, and the dead will be raised incorruptible, and we will be changed.'),
  ('5d24bfe2-4072-504b-abd6-752bb6bcacf1', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 53, 53, 'For this corruptible must put on incorruption, and this mortal must put on immortality.'),
  ('d5261058-f576-5413-a7c8-4ef411ffb1ea', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 54, 54, 'But when this corruptible will have put on incorruption, and this mortal will have put on immortality, then what is written will happen: "Death is swallowed up in victory."'),
  ('055d804d-2b38-5f7c-ac65-4a724844ae28', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 55, 55, '"Death, where is your sting? Hades, where is your victory?"'),
  ('eb7b9d8b-ce8d-55c7-a51a-715c78833043', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 56, 56, 'The sting of death is sin, and the power of sin is the law.'),
  ('79be7b60-8c3c-5d0e-afc2-9b608bd6b701', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 57, 57, 'But thanks be to God, who gives us the victory through our Lord Jesus Christ.'),
  ('25a13fad-60ca-591a-a087-78783c858973', 'ce2c83b9-435b-5d7c-ad6a-ba2c694ac155', NULL, 58, 58, 'Therefore, my beloved brothers, be steadfast, immovable, always abounding in the Lord''s work, because you know that your labor is not in vain in the Lord.'),
  ('6fffa533-0966-5278-a374-9cc3e4d12acf', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 1, 1, 'Now concerning the collection for the saints, as I commanded the assemblies of Galatia, you do likewise.'),
  ('1d2b7d76-18d0-5364-a560-077375f222b7', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 2, 2, 'On the first day of the week, let each one of you save, as he may prosper, that no collections be made when I come.'),
  ('2f9e756e-b0c9-5a22-ae29-6b0869137e6b', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 3, 3, 'When I arrive, I will send whoever you approve with letters to carry your gracious gift to Jerusalem.'),
  ('c67615fb-ebc5-5f7f-a419-c4cfb983fdd7', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 4, 4, 'If it is appropriate for me to go also, they will go with me.'),
  ('953ddcf6-8e82-50e5-ae7e-ccab82af2955', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 5, 5, 'But I will come to you when I have passed through Macedonia, for I am passing through Macedonia.'),
  ('1a45d12a-224c-57d3-a4af-267b30f50f6b', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 6, 6, 'But with you it may be that I will stay, or even winter, that you may send me on my journey wherever I go.'),
  ('0a8c2800-cdd4-5164-a6dc-249192aae597', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 7, 7, 'For I do not wish to see you now in passing, but I hope to stay a while with you, if the Lord permits.'),
  ('1eb706ba-2c2c-5361-aa4d-e93c765ccd6d', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 8, 8, 'But I will stay at Ephesus until Pentecost,'),
  ('8c84720b-35fa-59de-a6df-4f591ae6e93d', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 9, 9, 'for a great and effective door has opened to me, and there are many adversaries.'),
  ('8d73c93b-6425-5297-ab58-f1e78778ba64', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 10, 10, 'Now if Timothy comes, see that he is with you without fear, for he does the work of the Lord, as I also do.'),
  ('227f9db5-9a8f-52c5-a757-8184c6977a18', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 11, 11, 'Therefore let no one despise him. But set him forward on his journey in peace, that he may come to me; for I expect him with the brothers.'),
  ('0d663cfe-2bc1-5afb-a34b-5cf41715baf5', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 12, 12, 'Now concerning Apollos, the brother, I strongly urged him to come to you with the brothers; and it was not at all his desire to come now; but he will come when he has an opportunity.'),
  ('210dbd88-5194-57fd-a725-5ea2b2589992', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 13, 13, 'Watch! Stand firm in the faith! Be courageous! Be strong!'),
  ('9ed88b2c-a4d7-5b1b-af3b-c4a1ed91a817', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 14, 14, 'Let all that you do be done in love.'),
  ('126076d3-19b6-5172-ad13-660dd7500bb9', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 15, 15, 'Now I beg you, brothers (you know the house of Stephanas, that it is the first fruits of Achaia, and that they have set themselves to serve the saints),'),
  ('1a85a920-b6ae-5497-a136-a1ddfbe3f5ab', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 16, 16, 'that you also be in subjection to such, and to everyone who helps in the work and labors.'),
  ('0c32ff49-98af-5851-ae87-3f925b1eb2b6', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 17, 17, 'I rejoice at the coming of Stephanas, Fortunatus, and Achaicus; for that which was lacking on your part, they supplied.'),
  ('80619569-beaf-5f43-a8f3-a8fcf0281c34', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 18, 18, 'For they refreshed my spirit and yours. Therefore acknowledge those who are like that.'),
  ('caf2299a-6cd8-5744-a0b7-5c62960460d6', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 19, 19, 'The assemblies of Asia greet you. Aquila and Priscilla greet you much in the Lord, together with the assembly that is in their house.'),
  ('097c14a8-937f-59e2-a9af-8a25b4a6c861', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 20, 20, 'All the brothers greet you. Greet one another with a holy kiss.'),
  ('d2022f8b-1faf-5796-a50c-85f51e219e08', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 21, 21, 'This greeting is by me, Paul, with my own hand.'),
  ('cb94658a-6517-5006-a47a-719649510e86', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 22, 22, 'If any man doesn''t love the Lord Jesus Christ, let him be accursed. Come, Lord!'),
  ('091b3bc1-7cb5-51f7-ad39-2443496ca954', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 23, 23, 'The grace of the Lord Jesus Christ be with you.'),
  ('627df95b-5889-57c7-a13a-54eac6c0185a', 'eecdff10-eb90-5772-abb4-3f6125c6adee', NULL, 24, 24, 'My love to all of you in Christ Jesus. Amen.'),
  ('0684ca4a-56a4-57cd-a1a0-338708b5f547', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 1, 1, 'Paul, an apostle of Christ Jesus through the will of God, and Timothy our brother, to the assembly of God which is at Corinth, with all the saints who are in the whole of Achaia:'),
  ('a95ae3f5-5421-5375-afee-28d38e281594', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 2, 2, 'Grace to you and peace from God our Father and the Lord Jesus Christ.'),
  ('8b8715e1-4aea-5f13-a2df-4749cb446833', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 3, 3, 'Blessed be the God and Father of our Lord Jesus Christ, the Father of mercies and God of all comfort;'),
  ('f7980fde-63c5-5a1f-a85e-1a31e1c8b333', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 4, 4, 'who comforts us in all our affliction, that we may be able to comfort those who are in any affliction, through the comfort with which we ourselves are comforted by God.'),
  ('698ea8ea-9694-5f42-ae6d-05b5e8141ebd', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 5, 5, 'For as the sufferings of Christ abound to us, even so our comfort also abounds through Christ.'),
  ('e5725072-72c8-5faa-addf-8d477131ae5c', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 6, 6, 'But if we are afflicted, it is for your comfort and salvation. If we are comforted, it is for your comfort, which produces in you the patient enduring of the same sufferings which we also suffer.'),
  ('1371f34b-c511-5828-ab66-13e968e1ee84', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 7, 7, 'Our hope for you is steadfast, knowing that, since you are partakers of the sufferings, so also are you of the comfort.'),
  ('84f27e6e-2d74-570a-aa29-3b75ac2ecc9e', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 8, 8, 'For we don''t desire to have you uninformed, brothers, concerning our affliction which happened to us in Asia, that we were weighed down exceedingly, beyond our power, so much that we despaired even of life.'),
  ('ad8fcc44-541e-55e2-a303-cd9dc15eef33', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 9, 9, 'Yes, we ourselves have had the sentence of death within ourselves, that we should not trust in ourselves, but in God who raises the dead,'),
  ('0b9dbd73-bbea-5fe7-a507-b6b103aa7992', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 10, 10, 'who delivered us out of so great a death, and does deliver; on whom we have set our hope that he will also still deliver us;'),
  ('901a5fce-b4c0-53b2-ae1b-bdf238647c90', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 11, 11, 'you also helping together on our behalf by your supplication; that, for the gift bestowed on us by means of many, thanks may be given by many persons on your behalf.'),
  ('aafed95c-c98e-57d6-a916-61452c288ad8', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 12, 12, 'For our boasting is this: the testimony of our conscience, that in holiness and sincerity of God, not in fleshly wisdom but in the grace of God we behaved ourselves in the world, and more abundantly toward you.'),
  ('55dfde02-a494-5ade-a124-20178c5d29d8', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 13, 13, 'For we write no other things to you, than what you read or even acknowledge, and I hope you will acknowledge to the end;'),
  ('b3f7e6de-c778-5f79-af12-b4a30606cb5b', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 14, 14, 'as also you acknowledged us in part, that we are your boasting, even as you also are ours, in the day of our Lord Jesus.'),
  ('5af42023-379a-5138-a54a-15f187905f49', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 15, 15, 'In this confidence, I was determined to come first to you, that you might have a second benefit;'),
  ('0c40dddb-8591-55ac-ae11-41a656ed5d1e', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 16, 16, 'and by you to pass into Macedonia, and again from Macedonia to come to you, and to be sent forward by you on my journey to Judea.'),
  ('36200763-4491-5d6e-a223-372468c93863', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 17, 17, 'When I therefore was thus determined, did I show fickleness? Or the things that I purpose, do I purpose according to the flesh, that with me there should be the "Yes, yes" and the "No, no?"'),
  ('339794e4-6c70-59f6-af38-07d45814bafb', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 18, 18, 'But as God is faithful, our word toward you was not "Yes and no."'),
  ('b378b11c-600f-5e05-a6c3-5d42bdf19c4c', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 19, 19, 'For the Son of God, Jesus Christ, who was preached among you by us, by me, Silvanus, and Timothy, was not "Yes and no," but in him is "Yes."'),
  ('24ac9405-b1ce-5240-aef9-af6dec4e3b08', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 20, 20, 'For however many are the promises of God, in him is the "Yes." Therefore also through him is the "Amen," to the glory of God through us.'),
  ('c8bc2d65-d045-56cb-abb7-ce7cf0283c93', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 21, 21, 'Now he who establishes us with you in Christ, and anointed us, is God;'),
  ('40a900db-a239-532b-a8de-a1c104b76219', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 22, 22, 'who also sealed us, and gave us the down payment of the Spirit in our hearts.'),
  ('fe18b336-9377-5b46-a218-db04f196a734', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 23, 23, 'But I call God for a witness to my soul, that I didn''t come to Corinth to spare you.'),
  ('4451f4f3-ba43-5991-ac28-12ad691bed69', '8a1706d5-ec9b-5324-a59d-30d762e20b4f', NULL, 24, 24, 'Not that we have lordship over your faith, but are fellow workers with you for your joy. For you stand firm in faith.'),
  ('02405548-35ed-5f4a-aca2-88145174df8d', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 1, 1, 'But I determined this for myself, that I would not come to you again in sorrow.'),
  ('2eb268b3-60c8-5f47-a2bd-67a4bd67e4d6', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 2, 2, 'For if I make you sorry, then who will make me glad but he who is made sorry by me?'),
  ('0ef09c64-5ff2-567d-a24f-cb692911244c', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 3, 3, 'And I wrote this very thing to you, so that, when I came, I wouldn''t have sorrow from them of whom I ought to rejoice; having confidence in you all, that my joy would be shared by all of you.'),
  ('8f7c2cd7-3770-5e43-af94-e203810f69bb', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 4, 4, 'For out of much affliction and anguish of heart I wrote to you with many tears, not that you should be made sorry, but that you might know the love that I have so abundantly for you.'),
  ('2cab1f51-8aaa-5fbf-a9ba-f5e55b3fa162', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 5, 5, 'But if any has caused sorrow, he has caused sorrow, not to me, but in part (that I not press too heavily) to you all.'),
  ('681e3d6a-7bc9-5c65-a9eb-ab786b42e0fa', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 6, 6, 'Sufficient to such a one is this punishment which was inflicted by the many;'),
  ('7314da74-be1c-560b-a895-fbb46485a645', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 7, 7, 'so that on the contrary you should rather forgive him and comfort him, lest by any means such a one should be swallowed up with his excessive sorrow.'),
  ('75eb511d-6a25-5289-a595-32fa39f0a527', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 8, 8, 'Therefore I beg you to confirm your love toward him.'),
  ('75398a79-3342-52b9-aeeb-8e0c98ce01fd', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 9, 9, 'For to this end I also wrote, that I might know the proof of you, whether you are obedient in all things.'),
  ('7f4db708-f415-5834-ab73-521c08c2ce93', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 10, 10, 'Now I also forgive whomever you forgive anything. For if indeed I have forgiven anything, I have forgiven that one for your sakes in the presence of Christ,'),
  ('cf008481-a38d-50e1-a671-57cacf32e8db', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 11, 11, 'that no advantage may be gained over us by Satan; for we are not ignorant of his schemes.'),
  ('98a7c7fd-147a-5d54-a315-632f0a385233', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 12, 12, 'Now when I came to Troas for the Good News of Christ, and when a door was opened to me in the Lord,'),
  ('d01d25a6-d150-5d0d-ace5-3e945495f713', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 13, 13, 'I had no relief for my spirit, because I didn''t find Titus, my brother, but taking my leave of them, I went out into Macedonia.'),
  ('7eed1fc8-9306-5f44-a1e6-e76f0a04729d', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 14, 14, 'Now thanks be to God, who always leads us in triumph in Christ, and reveals through us the sweet aroma of his knowledge in every place.'),
  ('e34bf0b7-1b77-588a-a0b8-1d0b1ed6073c', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 15, 15, 'For we are a sweet aroma of Christ to God, in those who are saved, and in those who perish;'),
  ('ace43aac-0892-5fa1-afb3-1cc52c521407', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 16, 16, 'to the one a stench from death to death; to the other a sweet aroma from life to life. Who is sufficient for these things?'),
  ('5eb17569-d33e-5425-a668-466049eb6b83', 'a1994b88-f1d1-5b35-afb9-45ea92ba9932', NULL, 17, 17, 'For we are not as so many, peddling the word of God. But as of sincerity, but as of God, in the sight of God, we speak in Christ.'),
  ('1a8b7a97-33e7-5b59-a70c-c7a68af1fb43', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 1, 1, 'Are we beginning again to commend ourselves? Or do we need, as do some, letters of commendation to you or from you?'),
  ('142edcb5-16f5-57d4-ac68-7f7ad14a9985', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 2, 2, 'You are our letter, written in our hearts, known and read by all men;'),
  ('1a8aa01f-8a91-574e-ab45-3ebefb8f7848', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 3, 3, 'being revealed that you are a letter of Christ, served by us, written not with ink, but with the Spirit of the living God; not in tablets of stone, but in tablets that are hearts of flesh.'),
  ('e5b3704a-8211-5ecb-a820-e100fe4ae54f', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 4, 4, 'Such confidence we have through Christ toward God;'),
  ('729a8ffd-af4e-5bba-a23e-56f027607adc', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 5, 5, 'not that we are sufficient of ourselves, to account anything as from ourselves; but our sufficiency is from God;'),
  ('884dad89-4e20-5d7a-a72a-d08e4ed87ef0', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 6, 6, 'who also made us sufficient as servants of a new covenant; not of the letter, but of the Spirit. For the letter kills, but the Spirit gives life.'),
  ('8a8b17f8-9aa4-54c2-a385-a41038890f5c', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 7, 7, 'But if the service of death, written engraved on stones, came with glory, so that the children of Israel could not look steadfastly on the face of Moses for the glory of his face; which was passing away:'),
  ('13100491-7191-56fd-a9c3-f232690887f6', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 8, 8, 'won''t service of the Spirit be with much more glory?'),
  ('d0ca637e-73b5-5614-a6cb-2ff24aea4bcf', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 9, 9, 'For if the service of condemnation has glory, the service of righteousness exceeds much more in glory.'),
  ('81b689e6-9b0f-58d8-afdc-4f38a89d30c3', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 10, 10, 'For most certainly that which has been made glorious has not been made glorious in this respect, by reason of the glory that surpasses.'),
  ('d346d1fe-267f-534b-acd6-abfd90690e65', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 11, 11, 'For if that which passes away was with glory, much more that which remains is in glory.'),
  ('94ac670b-8d92-5171-a225-01085273d80d', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 12, 12, 'Having therefore such a hope, we use great boldness of speech,'),
  ('d94e147f-61a6-526b-a729-cd3119882ee1', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 13, 13, 'and not as Moses, who put a veil on his face, that the children of Israel wouldn''t look steadfastly on the end of that which was passing away.'),
  ('db2f9f0e-59c6-5799-a832-469ad0bf0af8', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 14, 14, 'But their minds were hardened, for until this very day at the reading of the old covenant the same veil remains, because in Christ it passes away.'),
  ('6540c8a8-91f5-5fe2-a28c-4581560e71f2', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 15, 15, 'But to this day, when Moses is read, a veil lies on their heart.'),
  ('d6fce145-0a0a-58f2-a4a1-802c2bb8b36e', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 16, 16, 'But whenever one turns to the Lord, the veil is taken away.'),
  ('58f3dc7e-c4a1-5df5-af76-631e9f365406', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 17, 17, 'Now the Lord is the Spirit and where the Spirit of the Lord is, there is liberty.'),
  ('d848a8c0-46ed-5a06-af93-f98fbc26b62b', '8660a8d9-607d-5807-a3c6-c778bceeb4c8', NULL, 18, 18, 'But we all, with unveiled face beholding as in a mirror the glory of the Lord, are transformed into the same image from glory to glory, even as from the Lord, the Spirit.')
